// 產生檔：node tools/build_course_v2.js（來源 tools/content/course_v2/）。不要手改。
window.BUZZ_COURSE_V2_LESSONS = Object.assign(window.BUZZ_COURSE_V2_LESSONS || {}, {"pointwise-convergence":{"id":"pointwise-convergence","prerequisites":["epsilon-n-definition","uniform-continuity","heine-cantor"],"next":["uniform-convergence"],"related":["limit-integral-swap"],"objectives":["把一列函數 $f_n$ 在每個固定的 $x$ 看成一個數列，求出極限函數 $f$。","寫出逐點收斂的量詞：$N$ 可以同時依賴 $\\varepsilon$ 與 $x$。","舉出三個例子：每個 $f_n$ 都連續，極限不連續；$f_n\\to0$ 但 $\\int f_n$ 不趨近 0；$f_n$ 的高峰一直不消失。"],"concept":[{"heading":"① 一列函數，在每個點各是一個數列","body":["函數列 $f_1,f_2,f_3,\\dots$ 是一串定義在同一個集合 $D$ 上的函數。固定一個 $x$，$f_1(x),f_2(x),f_3(x),\\dots$ 就是一個普通的數列，可以問它收不收斂。","例：$f_n(x)=x^n$，$x\\in[0,1]$。$x=0.5$ 時是 $0.5,0.25,0.125,\\dots\\to0$；$x=1$ 時是 $1,1,1,\\dots\\to1$。每個 $x$ 各算各的，得到極限函數 $f(x)=0$（$0\\le x<1$），$f(1)=1$。"]},{"heading":"② 定義","body":["$f_n$ 在 $D$ 上逐點收斂到 $f$，意思是對每一個 $x\\in D$，數列 $f_n(x)$ 收斂到 $f(x)$。把數列極限的 $\\varepsilon$-$N$ 定義展開：","量詞順序是「先固定 $x$，再給 $\\varepsilon$，再找 $N$」，所以 $N$ 可以隨 $x$ 改變。這一點下一課會變成關鍵。"],"tex":["\\forall x\\in D\\ \\ \\forall\\varepsilon>0\\ \\ \\exists N=N(\\varepsilon,x)\\ \\ \\forall n\\ge N:\\ |f_n(x)-f(x)|<\\varepsilon"]},{"heading":"③ 逐點收斂會弄丟什麼","body":["連續：每個 $x^n$ 都連續，極限 $f$ 在 $x=1$ 跳了一下。","積分：$f_n(x)=nx e^{-nx^2}$ 在 $[0,1]$ 上逐點收斂到 0，但 $\\int_0^1 f_n\\,dx=\\frac{1-e^{-n}}{2}\\to\\frac{1}{2}$，不是 $\\int_0^1 0\\,dx=0$（範例 3）。","直覺，不是證明：逐點收斂只保證每個點「最後」會靠近，但不同點靠近的速度可以差到沒有上限。高峰往 $x=0$ 擠、越來越窄，任何一個固定的點遲早都會被高峰甩在後面，但高峰本身從來沒消失。要把連續、積分保住，需要一個對所有 $x$ 共用的 $N$，那就是〈一致收斂〉。"]}],"workedExamples":[{"title":"$N$ 會隨 $x$ 改變","prompt":"$f_n(x)=x^n$，$\\varepsilon=0.01$。分別在 $x=0.5$、0.9、0.99 找最小的 $N$，使 $n\\ge N$ 時 $x^n<0.01$。","steps":["$0<x<1$ 時 $x^n$ 遞減，所以只要找第一個 $n$ 使 $x^n<0.01$。取對數：$n\\ln x<\\ln 0.01$，$\\ln x<0$，除過去要變號：$n>\\frac{\\ln 0.01}{\\ln x}$。","$x=0.5$：$\\frac{\\ln 0.01}{\\ln 0.5}\\approx6.64$，$N=7$。檢查：$0.5^6=0.015625\\ge0.01$，$0.5^7=0.0078125<0.01$。","$x=0.9$：$\\approx43.71$，$N=44$（$0.9^{43}\\approx0.01078$，$0.9^{44}\\approx0.00970$）。","$x=0.99$：$\\approx458.21$，$N=459$（$0.99^{458}\\approx0.01002$，$0.99^{459}\\approx0.00992$）。","$x$ 越靠近 1，$N$ 越大，而且沒有上限：給任何 $N$，取 $x=0.01^{1/N}<1$，就有 $x^N=0.01$，不小於 $\\varepsilon$。"],"answer":"$N=7$、44、459；沒有一個 $N$ 對所有 $x\\in[0,1)$ 都行"},{"title":"會移動的高峰","prompt":"$f_n(x)=\\frac{nx}{1+n^2x^2}$，$x\\in[0,1]$。求逐點極限，並求 $f_n$ 在 $[0,1]$ 上的最大值。","problemId":"an-uf-004","steps":["$x=0$：$f_n(0)=0$。$x>0$：$0\\le f_n(x)\\le\\frac{nx}{n^2x^2}=\\frac{1}{nx}\\to0$。所以逐點極限 $f\\equiv0$。","最大值：令 $t=nx\\ge0$，$f_n=\\frac{t}{1+t^2}$。由 $(t-1)^2\\ge0$ 得 $1+t^2\\ge2t$，所以 $\\frac{t}{1+t^2}\\le\\frac{1}{2}$，等號在 $t=1$，也就是 $x=\\frac{1}{n}$（落在 $[0,1]$ 內）。","所以每個 $n$ 的最大值都是 $f_n(\\frac{1}{n})=\\frac{1}{2}$：高峰一直在，只是往 0 擠。"],"answer":"逐點極限 0；每個 $f_n$ 的最大值都是 $\\frac{1}{2}$"},{"title":"逐點極限是 0，積分卻不是","prompt":"$f_n(x)=nx e^{-nx^2}$，$x\\in[0,1]$。比較 $\\lim\\int_0^1 f_n\\,dx$ 與 $\\int_0^1(\\lim f_n)\\,dx$。","problemId":"lb-con-003","steps":["逐點：$x=0$ 時 $f_n=0$。$x>0$ 時固定 $x$，$n e^{-nx^2}$ 中指數衰減贏過 $n$，$\\to0$。所以 $\\lim f_n\\equiv0$，$\\int_0^1 0\\,dx=0$。","積分：令 $u=nx^2$，$du=2nx\\,dx$，$\\int_0^1 nx e^{-nx^2}\\,dx=(\\frac{1}{2})\\int_0^n e^{-u}\\,du=\\frac{1-e^{-n}}{2}$。","$n\\to\\infty$：$\\frac{1-e^{-n}}{2}\\to\\frac{1}{2}$。","$\\frac{1}{2}\\ne0$：逐點收斂下，極限與積分不能隨便交換。"],"answer":"$\\lim\\int f_n=\\frac{1}{2}$，$\\int\\lim f_n=0$"}],"pitfalls":["把 $x^n$ 在 $[0,1]$ 的極限寫成 $f\\equiv0$，漏掉 $x=1$ 那一點 $1^n=1$。","以為「每個 $f_n$ 連續」就推得出「極限連續」。逐點收斂不保證。","以為逐點收斂就能交換極限與積分：$\\lim\\int f_n$ 與 $\\int\\lim f_n$ 可以不相等。","寫逐點收斂時把 $N$ 寫成只跟 $\\varepsilon$ 有關；它允許跟 $x$ 有關，這正是它弱的地方。"],"voice":"676a2a38","sections":[{"title":"每個點一個數列","beats":[{"show":["$f_1,f_2,f_3,\\dots$ 定義在同一個 $D$"],"note":"固定 $x$，$f_n(x)$ 就是一個數列。","say":"函數列是一串定義在同一個集合上的函數。固定一個 x，f n 在 x 的值排起來，就是一個普通數列。","t":[0,9912]},{"show":["$f_n(x)=x^n$，$x=0.5$：","$0.5,0.25,0.125,\\dots\\to0$"],"say":"例如 x 的 n 次方。x 是零點五時，數列是零點五、零點二五、零點一二五，往零走。","t":[9912,19440]},{"show":["$x=1$：$1,1,1,\\dots\\to1$"],"say":"x 等於一時，每一項都是一，極限是一。每個 x 各算各的。","t":[19440,26136]},{"show":["$f(x)=0$（$0\\le x<1$），$f(1)=1$"],"note":"極限函數在 $x=1$ 跳了一下。","say":"合起來，極限函數在零到一之前都是零，到 x 等於一跳成一。","t":[26136,32400]}],"check":0},{"title":"定義：先固定 $x$","beats":[{"show":["每個 $x\\in D$：$f_n(x)\\to f(x)$"],"say":"逐點收斂就是：對定義域裡每一個 x，那一串數列都收斂到 f 在 x 的值。","t":[32400,39552]},{"show":["$\\forall x\\ \\forall\\varepsilon>0\\ \\exists N(\\varepsilon,x)$"],"note":"$n\\ge N$ 時 $|f_n(x)-f(x)|<\\varepsilon$。","say":"把 epsilon N 定義寫開：先固定 x，再給 epsilon，再找 N。","t":[39552,45432]},{"show":["$N$ 可以隨 $x$ 改變"],"note":"下一課這一點會變成關鍵。","say":"因為 x 先選好了，N 可以看 x 的臉色決定。這正是逐點收斂弱的地方。","t":[45432,52896]}],"check":2},{"title":"$N$ 跟著 $x$ 跑","beats":[{"show":["$x^n<0.01$，找最小的 $N$"],"note":"$0<x<1$ 時 $x^n$ 遞減。","say":"拿 x 的 n 次方，epsilon 取零點零一，在不同的點各找最小的 N。","t":[52896,58992]},{"show":["$n>\\frac{\\ln 0.01}{\\ln x}$"],"note":"$\\ln x<0$，除過去要變號。","say":"兩邊取自然對數。自然對數 x 是負的，除過去不等號要翻過來。","t":[58992,66096]},{"show":["$x=0.5$：$\\approx6.64$，$N=7$"],"note":"$0.5^6=0.015625$，$0.5^7=0.0078125$。","say":"x 是零點五，算出約六點六四，所以 N 是七。六次方還太大，七次方才小於零點零一。","t":[66096,75720]}],"check":1},{"title":"$N$ 沒有上限","beats":[{"show":["$x=0.99$：$N=459$"],"note":"$x=0.5$ 要 7，$x=0.9$ 要 44。","say":"x 推到零點九九，N 要四百五十九。越靠近一，要走的項數越多。","t":[75720,83040]},{"show":["取 $x=0.01^{1/N}<1$","$\\Rightarrow x^N=0.01$"],"say":"而且沒有上限：你說一個 N，我就挑一個夠靠近一的 x，讓它的 N 次方剛好等於零點零一。","t":[83040,91344]}],"predict":{"ask":"有沒有一個 $N$ 對所有 $x\\in[0,1)$ 都行？","options":[{"label":"沒有","correct":true},{"label":"有，取 $N=459$","why":"459 只夠 $x=0.99$；$x$ 再靠近 1，$N$ 還要更大。"},{"label":"有，取 $N=7$","why":"7 只夠 $x=0.5$；$x=0.9$ 就要 44。"}]}},{"title":"會移動的高峰","beats":[{"show":["$f_n(x)=\\frac{nx}{1+n^2x^2}$，$x\\in[0,1]$"],"say":"再看一個例子：分子 n x，分母一加 n 平方 x 平方。","t":[91344,96744]},{"show":["$0\\le f_n(x)\\le\\frac{1}{nx}\\to0$"],"note":"$x=0$ 時本來就是 0。","say":"固定 x 大於零，它被 n x 分之一壓住，往零走；x 等於零時本來就是零。逐點極限是零。","t":[96744,106296]},{"show":["$t=nx$：$\\frac{t}{1+t^2}\\le\\frac{1}{2}$"],"note":"等號在 $x=\\frac{1}{n}$。","say":"可是令 t 等於 n x，它最大是二分之一，發生在 x 等於 n 分之一。","t":[106296,112944]},{"show":["高峰一直在，只是往 0 擠"],"say":"每個 n 的高峰都是二分之一，只是位置往零擠，任何固定的點遲早被甩在後面。","t":[112944,120624]}],"check":3},{"title":"積分也會掉","beats":[{"show":["$f_n(x)=nx e^{-nx^2}$ 在 $[0,1]$"],"note":"固定 $x>0$，指數衰減贏過 $n$。","say":"最後一個：n x 乘 e 的負 n x 平方。固定 x，指數衰減贏過 n，逐點極限是零。","t":[120624,129408]},{"show":["$\\int_0^1 0\\,dx=0$"],"say":"所以先取極限再積分，得到零。","t":[129408,133128]},{"show":["$\\int_0^1 f_n\\,dx=\\frac{1-e^{-n}}{2}$"],"note":"令 $u=nx^2$。","say":"反過來先積分：令 u 等於 n x 平方，積出來是一減 e 的負 n 次方，再除以二。","t":[133128,140760]}],"predict":{"ask":"$n\\to\\infty$，$\\int_0^1 f_n\\,dx$ 趨近？","options":[{"label":"$\\frac{1}{2}$","correct":true},{"label":"0","why":"0 是先取極限再積分的結果；這裡 $e^{-n}\\to0$，所以 $\\frac{1-e^{-n}}{2}\\to\\frac{1}{2}$。"},{"label":"1","why":"別忘了除以 2：$\\frac{1-e^{-n}}{2}\\to\\frac{1}{2}$。"}]}}],"checks":[{"ask":"$f_n(x)=x^n$ 在 $[0,1]$ 上的逐點極限 $f$ 是？","options":[{"label":"$f(x)=0$（$0\\le x<1$），$f(1)=1$","correct":true},{"label":"$f\\equiv0$","why":"你看了 $x<1$ 的部分就下結論。$x=1$ 時數列是 1, 1, 1, …，極限是 1。"},{"label":"極限不存在，因為 $f$ 不連續","why":"你把「極限函數不連續」當成「不收斂」。每個 $x$ 的數列都收斂，只是收斂到一個不連續的函數。"}]},{"ask":"$f_n(x)=x^n$，$x=0.9$，$\\varepsilon=0.01$。使 $n\\ge N$ 時 $x^n<\\varepsilon$ 的最小 $N$ 是？","options":[{"label":"44","correct":true},{"label":"43","why":"你把 $\\frac{\\ln 0.01}{\\ln 0.9}\\approx43.71$ 無條件捨去了。$0.9^{43}\\approx0.0108$ 還不小於 0.01，要進位成 44。"},{"label":"7","why":"那是 $x=0.5$ 的答案。逐點收斂的 $N$ 隨 $x$ 改變，不能拿別的點的 $N$ 來用。"}]},{"ask":"逐點收斂的定義裡，$N$ 可以依賴什麼？","options":[{"label":"$\\varepsilon$ 與 $x$ 都可以","correct":true},{"label":"只能依賴 $\\varepsilon$","why":"那是一致收斂的要求（$\\forall\\varepsilon\\ \\exists N\\ \\forall x$）。逐點收斂先固定 $x$ 才找 $N$。"},{"label":"只能依賴 $x$","why":"$N$ 一定要能隨 $\\varepsilon$ 變大；$\\varepsilon$ 越小，通常要走越多項。"}]},{"ask":"$f_n(x)=\\frac{nx}{1+n^2x^2}$ 在 $[0,1]$ 上，下列何者正確？","options":[{"label":"逐點收斂到 0，但每個 $f_n$ 的最大值都是 $\\frac{1}{2}$","correct":true},{"label":"逐點收斂到 $\\frac{1}{2}$","why":"$\\frac{1}{2}$ 是高峰的高度，可是高峰位置 $\\frac{1}{n}$ 一直在移動；任何固定的 $x$ 上，$f_n(x)\\le\\frac{1}{nx}\\to0$。"},{"label":"在 $x$ 靠近 0 的地方不收斂","why":"你把高峰往 0 擠誤當成某個點不收斂。$x=0$ 時 $f_n(0)=0$；$x>0$ 時也 $\\to0$。每個點都收斂。"}]}],"practice":[{"id":"an-uf-004","core":true},{"id":"lb-con-004","core":true},{"id":"lb-con-003","core":true},{"id":"lb-con-005"},{"id":"lb-con-001","challenge":true,"note":"挑戰：$n^2x e^{-nx}$ 逐點收斂到 0，令 $u=nx$ 算出 $\\int_0^1=1-(n+1)e^{-n}$。"}]},"uniform-convergence":{"id":"uniform-convergence","prerequisites":["pointwise-convergence","uniform-continuity"],"next":["uniform-convergence-tests"],"related":["continuity-formal"],"objectives":["寫出一致收斂的定義（$\\forall\\varepsilon\\ \\exists N\\ \\forall n\\ge N\\ \\forall x$），說得出它跟逐點收斂差在量詞順序。","用 $\\sup$ 範數 $\\|f_n-f\\|_\\infty$ 判斷一致收斂，並會寫出「不一致收斂」的否定句。","證明並使用：連續函數列一致收斂，極限仍連續。"],"concept":[{"heading":"① 一根管子套住整條曲線","body":["以極限函數 $f$ 為中心，畫一條上下寬 $\\varepsilon$ 的管子。一致收斂的意思是：從某個 $N$ 開始，每一個 $f_n$ 的整條圖形都落在管子裡。逐點收斂只要求每個 $x$ 各自最後落進去，各點可以有各自的 $N$。","直覺，不是證明：逐點收斂是「每個人最後都會到」，一致收斂是「同一個時刻，所有人都已經到了」。"]},{"heading":"② 定義與 $\\sup$ 範數","body":["$f_n$ 在 $D$ 上一致收斂到 $f$：對每個 $\\varepsilon>0$，存在只跟 $\\varepsilon$ 有關的 $N$，使得所有 $n\\ge N$ 與所有 $x\\in D$ 都有 $|f_n(x)-f(x)|<\\varepsilon$。","把「所有 $x$」收進一個數：$\\|f_n-f\\|_\\infty=\\sup_{x\\in D}|f_n(x)-f(x)|$。一致收斂若且唯若 $\\|f_n-f\\|_\\infty\\to0$。兩者等價，因為 $|f_n(x)-f(x)|<\\varepsilon$ 對所有 $x$ 成立推得 $\\sup\\le\\varepsilon$，而 $\\sup<\\varepsilon$ 又推回每一點都 $<\\varepsilon$；$\\varepsilon$ 可任取，差一個等號不影響。","否定（不一致收斂）：存在 $\\varepsilon_0>0$，對每個 $N$，都有 $n\\ge N$ 與 $x\\in D$ 使 $|f_n(x)-f(x)|\\ge\\varepsilon_0$。實務上就是找一串點 $x_n$，讓誤差停在 $\\varepsilon_0$ 以上。"],"tex":["\\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N\\ \\forall x\\in D:\\ |f_n(x)-f(x)|<\\varepsilon\\iff\\|f_n-f\\|_\\infty\\to0"]},{"heading":"③ 一致收斂保住連續","body":["定理：若每個 $f_n$ 在 $D$ 上連續，且 $f_n$ 在 $D$ 上一致收斂到 $f$，則 $f$ 在 $D$ 上連續。","反過來用：連續函數列的逐點極限若不連續，收斂就一定不是一致的。$x^n$ 在 $[0,1]$ 上就是這樣。但注意逆命題不成立：極限連續，不代表收斂是一致的（範例 2）。"]},{"heading":"證明：連續函數列的一致極限連續（$\\frac{\\varepsilon}{3}$ 論證）","body":["固定 $a\\in D$ 與 $\\varepsilon>0$。由一致收斂，取一個 $N$ 使 $|f_N(x)-f(x)|<\\frac{\\varepsilon}{3}$ 對所有 $x\\in D$ 成立。$f_N$ 在 $a$ 連續，所以有 $\\delta>0$ 使 $x\\in D$、$|x-a|<\\delta$ 時 $|f_N(x)-f_N(a)|<\\frac{\\varepsilon}{3}$。","於是 $|x-a|<\\delta$ 時，$|f(x)-f(a)|\\le|f(x)-f_N(x)|+|f_N(x)-f_N(a)|+|f_N(a)-f(a)|<\\frac{\\varepsilon}{3}+\\frac{\\varepsilon}{3}+\\frac{\\varepsilon}{3}=\\varepsilon$。","一致性用在哪裡：第一項要在 $a$ 附近的每一個 $x$ 都小於 $\\frac{\\varepsilon}{3}$，而且用的是同一個 $N$（$\\delta$ 是由這個 $N$ 決定的）。如果只有逐點收斂，$N$ 會隨 $x$ 變，就沒有一個固定的 $f_N$ 可以拿來找 $\\delta$。"],"collapsible":true}],"workedExamples":[{"title":"$x^n$ 在 $[0,\\frac{1}{2}]$ 上一致收斂","prompt":"$f_n(x)=x^n$，$D=[0,\\frac{1}{2}]$。判斷是否一致收斂到 0；$\\varepsilon=0.001$ 時 $N$ 取多少？","problemId":"an-uf-002","steps":["逐點極限：$0\\le x\\le\\frac{1}{2}$ 時 $x^n\\to0$，$f\\equiv0$。","$x^n$ 在 $[0,\\frac{1}{2}]$ 上遞增，最大值在右端：$\\|f_n-0\\|_\\infty=(\\frac{1}{2})^n\\to0$，所以一致收斂。","要 $(\\frac{1}{2})^n<0.001$：$(\\frac{1}{2})^9\\approx0.00195$ 不夠，$(\\frac{1}{2})^{10}=\\frac{1}{1024}\\approx0.000977$ 夠。$N=10$ 對區間上每一個 $x$ 同時有效。"],"answer":"一致收斂；$\\varepsilon=0.001$ 時 $N=10$"},{"title":"極限連續，仍然不一致：$x^n$ 在 $[0,1)$","prompt":"$f_n(x)=x^n$，$D=[0,1)$。逐點極限是 $f\\equiv0$（連續）。收斂是一致的嗎？","problemId":"an-uf-001","steps":["$\\|f_n-0\\|_\\infty=\\sup_{0\\le x<1} x^n$。$x\\to1^-$ 時 $x^n\\to1$，所以 $\\sup=1$，對每個 $n$ 都是 1，不趨近 0。不一致收斂。","用否定句寫：取 $\\varepsilon_0=\\frac{1}{4}$ 與 $x_n=1-\\frac{1}{n}$（$n\\ge2$，落在 $[0,1)$ 內），$f_n(x_n)=(1-\\frac{1}{n})^n\\ge(\\frac{1}{2})^2=\\frac{1}{4}$。因為 $(1-\\frac{1}{n})^n$ 對 $n$ 遞增，$n=2$ 時最小。","附帶：在 $[0,1]$ 上（加入 $x=1$）極限不連續，由觀念 ③ 直接知道不一致。"],"answer":"不一致收斂（$\\|f_n\\|_\\infty=1$）","note":"$(1-\\frac{1}{n})^n\\to\\frac{1}{e}\\approx0.368$，所以誤差最後停在 $\\frac{1}{e}$ 附近，不會消失。"},{"title":"高峰越來越高","prompt":"$f_n(x)=nx e^{-nx^2}$ 在 $[0,1]$ 上逐點收斂到 0。求 $\\|f_n\\|_\\infty$，判斷是否一致收斂。","problemId":"an-uf-003","steps":["$f_n'(x)=n e^{-nx^2}(1-2nx^2)$，在 $x=\\frac{1}{\\sqrt{2n}}$ 由正變負，這是 $[0,1]$ 上的最大值點（$\\frac{1}{\\sqrt{2n}}\\le1$）。","$\\|f_n\\|_\\infty=f_n(\\frac{1}{\\sqrt{2n}})=n\\cdot(\\frac{1}{\\sqrt{2n}})\\cdot e^{-1/2}=\\sqrt{\\frac{n}{2}}\\cdot e^{-1/2}$。","$n=8$ 時是 $2e^{-1/2}\\approx1.213$；一般 $n$ 時 $\\to\\infty$，不趨近 0，所以不一致收斂。"],"answer":"$\\|f_n\\|_\\infty=\\sqrt{\\frac{n}{2}}\\cdot e^{-1/2}\\to\\infty$，不一致收斂"}],"pitfalls":["量詞寫成「$\\forall x\\ \\exists N$」：那是逐點收斂。一致收斂的 $N$ 要在 $x$ 之前選定。","用「極限函數連續」證明一致收斂。定理只能單向用：極限不連續 $\\Rightarrow$ 不一致；極限連續什麼都推不出。","算 $\\|f_n-f\\|_\\infty$ 時只代端點，漏掉內部的最大值點（例如 $nx e^{-nx^2}$ 的高峰在 $\\frac{1}{\\sqrt{2n}}$）。","在開區間上找不到最大值，就以為 $\\sup$ 不存在；$\\sup$ 可以取不到，例如 $\\sup_{[0,1)} x^n=1$。"],"voice":"31ea9f58","sections":[{"title":"一根管子","beats":[{"show":["以 $f$ 為中心，上下寬 $\\varepsilon$ 的管子"],"say":"以極限函數為中心，上下各畫寬 epsilon 的一根管子。","t":[0,5208]},{"show":["從某個 $N$ 起，每個 $f_n$ 整條都在管子裡"],"note":"逐點收斂：各點各自最後落進去。","say":"一致收斂是說：從某個 N 開始，每一個 f n 的整條圖形都塞進管子裡，不是各點各自慢慢進去。","t":[5208,14184]},{"show":["逐點：每個人最後都會到","一致：同一刻，所有人都到了"],"say":"打個比方，逐點收斂是每個人最後都會到；一致收斂是同一個時刻，所有人都已經到了。","t":[14184,22800]},{"show":["$\\forall\\varepsilon\\ \\exists N\\ \\forall n\\ge N\\ \\forall x$"],"note":"$N$ 要在 $x$ 之前選定。","say":"寫成量詞：先給 epsilon，找一個 N，然後對所有 n 跟所有 x 都成立。N 只跟 epsilon 有關。","t":[22800,32112]}],"check":0},{"title":"收成一個數","beats":[{"show":["$\\|f_n-f\\|_\\infty=\\sup_{x\\in D}|f_n(x)-f(x)|$"],"say":"把所有 x 的誤差收成一個數：取上確界，叫 sup 範數，也就是最大的那個誤差。","t":[32112,39648]},{"show":["一致收斂 $\\iff\\|f_n-f\\|_\\infty\\to0$"],"say":"一致收斂，就是這個最大誤差趨近零。判斷一致收斂，通常就是算它。","t":[39648,47424]},{"show":["$x^n$ 在 $[0,\\frac{1}{2}]$：最大在右端"],"note":"$x^n$ 在這裡遞增。","say":"例如 x 的 n 次方在零到二分之一，函數遞增，最大誤差發生在右端點。","t":[47424,54720]},{"show":["$(\\frac{1}{2})^{10}=\\frac{1}{1024}<0.001$"],"note":"$\\varepsilon=0.001$ 時 $N=10$，每個 $x$ 都有效。","say":"epsilon 取零點零零一，二分之一的九次方還不夠，十次方是一千零二十四分之一，夠了，N 等於十。","t":[54720,64224]}],"check":1},{"title":"一致收斂保住連續","beats":[{"show":["$f_n$ 都連續、一致收斂到 $f$","$\\Rightarrow f$ 連續"],"say":"定理：每個 f n 都連續，又一致收斂到 f，那 f 也連續。","t":[64224,70152]},{"show":["$\\frac{\\varepsilon}{3}+\\frac{\\varepsilon}{3}+\\frac{\\varepsilon}{3}=\\varepsilon$"],"note":"固定一個 $f_N$，誤差拆成三段。","say":"證明的點子是拿一個固定的 f N 當跳板，把誤差拆成三段，每段小於三分之 epsilon。證明在下一節。","t":[70152,79896]},{"show":["只有逐點：沒有固定的 $f_N$ 可用"],"say":"一致性就用在這裡：N 不能隨 x 變，才有一個固定的 f N 可以拿來找 delta。","t":[79896,86784]}],"check":2},{"title":"證明：拆成三段","proof":true,"of":3,"skeleton":"ε-δ","beats":[{"show":["固定一個 $f_N$ 當跳板，誤差拆三段"],"say":"策略：epsilon 三分法。固定一個 f N 當跳板，把 f 在 x 跟 f 在 a 的差拆成三段。","t":[86784,95088]},{"show":["取 $N$：$|f_N(x)-f(x)|<\\frac{\\varepsilon}{3}$，$\\forall x\\in D$"],"note":"一致：同一個 $N$。","say":"先用一致收斂取一個 N，讓 f N 跟 f 的距離，在每一個 x 都小於三分之 epsilon。","t":[95088,102336]},{"show":["$f_N$ 在 $a$ 連續：取 $\\delta$"],"note":"$|x-a|<\\delta$ ⇒ $|f_N(x)-f_N(a)|<\\frac{\\varepsilon}{3}$。","why":{"ask":"為什麼 $\\delta$ 要在 $N$ 之後才找？","say":"delta 為什麼要等 N 選好才找？","options":[{"label":"$\\delta$ 是從 $f_N$ 的連續找的，要先固定 $f_N$","correct":true},{"label":"$\\delta$ 只跟 $\\varepsilon$ 有關，先找後找都一樣","why":"這個 $\\delta$ 是 $f_N$ 在 $a$ 連續給的；換一個 $N$，可能就要換一個 $\\delta$。"},{"label":"要等 $f$ 連續才能找 $\\delta$","why":"$f$ 連續正是要證的結論；這裡能用的只有 $f_N$ 連續。"}],"t":[102336,105576]},"say":"這個 delta 是 f N 在 a 連續給的，所以要先把 f N 固定下來，才找得到它。","t":[105576,112464]},{"show":["$|f(x)-f(a)|\\le|f(x)-f_N(x)|$","$+|f_N(x)-f_N(a)|+|f_N(a)-f(a)|$"],"say":"三角不等式：中間插進 f N 在 x 跟 f N 在 a，拆成三段。","t":[112464,118632]},{"show":["$<\\frac{\\varepsilon}{3}+\\frac{\\varepsilon}{3}+\\frac{\\varepsilon}{3}=\\varepsilon$"],"note":"第一、三段靠 $N$，中間靠 $\\delta$。","why":{"ask":"第一段為什麼也 $<\\frac{\\varepsilon}{3}$？","say":"第一段是在 x 量的。它為什麼也小於三分之 epsilon？","options":[{"label":"$N$ 對每一個 $x$ 都有效，包括這個 $x$","correct":true},{"label":"$x$ 離 $a$ 很近，跟第三段差不多","why":"近不代表誤差一樣小；第一段是在 $x$ 量的，靠的是同一個 $N$ 對所有 $x$ 都成立。"},{"label":"$f_N$ 在 $a$ 連續","why":"連續管的是中間那段 $f_N(x)$ 與 $f_N(a)$；第一段比的是 $f$ 跟 $f_N$。"}],"t":[118632,124392]},"say":"N 是一致收斂給的，對每一個 x 都有效，所以第一段也小於三分之 epsilon。三段加起來小於 epsilon。","t":[124392,134016]}],"order":{"ask":"把證明排回順序：依序點每一步","steps":[{"label":"固定 $a$ 與 $\\varepsilon>0$"},{"label":"由一致收斂取 $N$","why":"要先有 $\\varepsilon$，才知道 $N$ 要讓誤差小於多少。"},{"label":"由 $f_N$ 在 $a$ 連續取 $\\delta$","why":"$\\delta$ 是 $f_N$ 給的：要先固定 $N$。"},{"label":"$|x-a|<\\delta$ 時三段相加 $<\\varepsilon$","why":"要先有 $\\delta$，才知道哪些 $x$ 算數。"}]}},{"title":"極限連續也不保證","beats":[{"show":["$x^n$ 在 $[0,1]$：極限在 1 跳"],"note":"所以不一致。","say":"反過來用：x 的 n 次方在零到一，極限在一跳了一下，所以收斂一定不一致。","t":[134016,141528]},{"show":["$x^n$ 在 $[0,1)$：極限 $f\\equiv0$ 連續"],"say":"把一拿掉，在零到一不含一，極限是零，連續了。那這樣就一致了嗎？","t":[141528,149304]},{"show":["$\\sup_{0\\le x<1}x^n=1$"],"note":"取不到，但 $\\sup$ 還是 1。","say":"x 往一靠，x 的 n 次方往一靠，所以最大誤差的上確界對每個 n 都是一，不趨近零。","t":[149304,157344]}],"check":3},{"title":"高峰越來越高","beats":[{"show":["$f_n(x)=nx e^{-nx^2}$ 在 $[0,1]$"],"note":"逐點收斂到 0。","say":"上一課的 n x 乘 e 的負 n x 平方，逐點收斂到零。現在算它的最大誤差。","t":[157344,165216]},{"show":["$f_n'(x)=n e^{-nx^2}(1-2nx^2)$"],"note":"最大值點 $x=\\frac{1}{\\sqrt{2n}}$。","say":"微分，導數在 x 等於根號二 n 分之一由正變負，那是最高點，不在端點。","t":[165216,172584]}],"predict":{"ask":"$\\|f_n\\|_\\infty$ 是？","options":[{"label":"$\\sqrt{\\frac{n}{2}}\\cdot e^{-1/2}$，趨向無限大","correct":true},{"label":"$\\frac{1}{\\sqrt{2n}}$","why":"那是高峰的位置；高度要代回去：$n\\cdot\\frac{1}{\\sqrt{2n}}\\cdot e^{-1/2}$。"},{"label":"0","why":"0 是逐點極限，也是 $f_n(0)$；$\\sup$ 要看內部的最大值點。"}]}}],"checks":[{"ask":"下列哪一句是一致收斂？","options":[{"label":"$\\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N\\ \\forall x\\in D$：$|f_n(x)-f(x)|<\\varepsilon$","correct":true},{"label":"$\\forall x\\in D\\ \\forall\\varepsilon>0\\ \\exists N\\ \\forall n\\ge N$：$|f_n(x)-f(x)|<\\varepsilon$","why":"你把 $\\forall x$ 放到最前面，$N$ 就可以隨 $x$ 變，這是逐點收斂。"},{"label":"$\\exists N\\ \\forall\\varepsilon>0\\ \\forall n\\ge N\\ \\forall x\\in D$：$|f_n(x)-f(x)|<\\varepsilon$","why":"你把 $\\exists N$ 移到 $\\forall\\varepsilon$ 前面，等於同一個 $N$ 要對所有 $\\varepsilon$ 都行，逼出 $n\\ge N$ 時 $f_n=f$，太強了。"}]},{"ask":"$f_n(x)=x^n$ 在 $[0,\\frac{1}{2}]$ 上，$\\|f_n-0\\|_\\infty$ 是？","options":[{"label":"$(\\frac{1}{2})^n$","correct":true},{"label":"0","why":"你代了左端點 $x=0$。$\\sup$ 要看整個區間，$x^n$ 遞增，最大在 $x=\\frac{1}{2}$。"},{"label":"1","why":"那是 $[0,1)$ 上的 $\\sup$。這裡 $x$ 最大只到 $\\frac{1}{2}$。"}]},{"ask":"每個 $f_n$ 都連續，逐點極限 $f$ 在某點不連續。可以推出什麼？","options":[{"label":"$f_n$ 不是一致收斂到 $f$","correct":true},{"label":"$f_n$ 不是逐點收斂","why":"題目說了逐點極限存在。定理告訴你的是「不一致」，不是「不收斂」。"},{"label":"什麼都推不出","why":"連續函數列的一致極限必連續；取逆否，極限不連續就不可能一致。"}]},{"ask":"$x^n$ 在 $[0,1)$ 上逐點收斂到 0（連續函數）。收斂是一致的嗎？","options":[{"label":"不是，$\\sup_{[0,1)} x^n=1$ 不趨近 0","correct":true},{"label":"是，因為極限函數 0 連續","why":"你把定理反過來用了。「一致 $\\Rightarrow$ 極限連續」的逆命題不成立。"},{"label":"是，因為每個 $x<1$ 都有 $x^n\\to0$","why":"那只是逐點收斂。$x$ 越靠近 1 要的 $N$ 越大，沒有共用的 $N$。"}]}],"practice":[{"id":"an-uf-002","core":true},{"id":"an-uf-001","core":true},{"id":"an-uf-004","core":true},{"id":"an-uf-003","core":true},{"id":"an-uf-005","challenge":true,"note":"挑戰：用上一題的 $\\|f_n\\|_\\infty\\to\\infty$ 寫出否定句：取 $\\varepsilon_0$ 與 $x_n=\\frac{1}{\\sqrt{2n}}$。"}]},"uniform-convergence-tests":{"id":"uniform-convergence-tests","prerequisites":["uniform-convergence","bolzano-weierstrass","extreme-value-theorem"],"next":["weierstrass-m-test"],"related":[],"objectives":["照固定流程判斷：先求逐點極限，再算或估計 $\\|f_n-f\\|_\\infty$。","會用三種工具：微分求 $\\sup$、找與 $x$ 無關的上界、找一串點 $x_n$ 證明不一致。","知道「縮小定義域」常常把不一致變成一致，並會用 Dini 定理。"],"concept":[{"heading":"① 第一步永遠是逐點極限","body":["一致收斂問的是「$f_n$ 一致收斂到誰」。所以先固定 $x$ 求 $f(x)=\\lim f_n(x)$；沒有 $f$，就沒有 $\\|f_n-f\\|_\\infty$ 可算。逐點極限不存在，一致收斂當然也不成立。"]},{"heading":"② 三種工具","body":["算出來：把 $g_n(x)=|f_n(x)-f(x)|$ 當成 $x$ 的函數，用微分找最大值，得到 $\\|f_n-f\\|_\\infty$ 的公式，看它是否 $\\to0$。","估出來：不必算到精確，只要找到與 $x$ 無關的 $a_n\\to0$，使 $|f_n(x)-f(x)|\\le a_n$ 對所有 $x$ 成立。例如 $\\left|\\frac{\\sin(nx)}{n}\\right|\\le\\frac{1}{n}$。","否定：要證不一致，找一串點 $x_n\\in D$ 使 $|f_n(x_n)-f(x_n)|$ 不趨近 0。最常見的 $x_n$ 是高峰的位置，例如 $\\frac{1}{n}$、$\\frac{1}{\\sqrt{n}}$、$1-\\frac{1}{n}$。另一條捷徑：每個 $f_n$ 連續而 $f$ 不連續，就不一致。"]},{"heading":"③ 壞事通常發生在一個點附近","body":["$\\frac{nx}{1+n^2x^2}$ 在 $[0,1]$ 上不一致，是因為高峰擠向 $x=0$；把定義域改成 $[\\frac{1}{2},1]$，高峰在 $n\\ge2$ 時就跑出定義域，收斂變成一致的（範例 2）。很多「在 $D$ 上不一致、但在每個遠離壞點的閉子區間上一致」的例子都是這種形狀。"]},{"heading":"④ Dini 定理","body":["若 (1) $D=[a,b]$ 是有界閉區間；(2) 每個 $f_n$ 連續；(3) 極限 $f$ 連續；(4) 對每個 $x$，$f_n(x)$ 對 $n$ 單調；則 $f_n\\to f$ 一致收斂。","四個條件都要：$x^n$ 在 $[0,1]$ 上滿足 (1)(2)(4)，缺 (3)，不一致；$x^n$ 在 $[0,1)$ 上滿足 (2)(3)(4)，缺 (1)，也不一致。"],"collapsible":true},{"heading":"證明：Dini 定理","body":["不妨設 $f_n$ 對 $n$ 遞減（遞增時改看 $-f_n$）。令 $g_n=f_n-f$：每個 $g_n$ 連續、$g_n\\ge0$、$g_n(x)$ 對 $n$ 遞減且 $\\to0$。因為 $g_{n+1}\\le g_n$，$\\|g_n\\|_\\infty$ 對 $n$ 遞減。","反設不一致，則 $\\|g_n\\|_\\infty$ 不趨近 0，又因為遞減，有 $\\varepsilon_0>0$ 使 $\\|g_n\\|_\\infty\\ge\\varepsilon_0$ 對所有 $n$ 成立。$g_n$ 在 $[a,b]$ 上連續，由極值定理取得到最大值，取 $x_n$ 使 $g_n(x_n)\\ge\\varepsilon_0$。","由 Bolzano–Weierstrass，有子數列 $x_{n_k}\\to x^*\\in[a,b]$。固定 $m$；當 $n_k\\ge m$ 時，$g_m(x_{n_k})\\ge g_{n_k}(x_{n_k})\\ge\\varepsilon_0$。令 $k\\to\\infty$，$g_m$ 連續，得 $g_m(x^*)\\ge\\varepsilon_0$。這對每個 $m$ 成立，和 $g_m(x^*)\\to0$ 矛盾。"],"collapsible":true}],"workedExamples":[{"title":"找與 $x$ 無關的上界","prompt":"$f_n(x)=\\frac{x}{1+nx^2}$，$x\\in\\mathbb{R}$。是否一致收斂？","steps":["逐點極限：$x=0$ 時 $f_n=0$；$x\\ne0$ 時分母 $\\to\\infty$，$f_n(x)\\to0$。$f\\equiv0$。","估計：由 $(\\sqrt{n}|x|-1)^2\\ge0$ 得 $1+nx^2\\ge2\\sqrt{n}|x|$，所以 $|f_n(x)|\\le|x|/(2\\sqrt{n}|x|)=\\frac{1}{2\\sqrt{n}}$（$x\\ne0$；$x=0$ 時顯然）。","上界 $\\frac{1}{2\\sqrt{n}}$ 跟 $x$ 無關且 $\\to0$，所以在整條實數線上一致收斂。等號在 $x=\\frac{1}{\\sqrt{n}}$ 取到，所以 $\\|f_n\\|_\\infty$ 恰好是 $\\frac{1}{2\\sqrt{n}}$。"],"answer":"一致收斂，$\\|f_n\\|_\\infty=\\frac{1}{2\\sqrt{n}}$"},{"title":"縮小定義域","prompt":"$f_n(x)=\\frac{nx}{1+n^2x^2}$。在 $[0,1]$ 與 $[\\frac{1}{2},1]$ 上分別判斷是否一致收斂到 0。","problemId":"an-uf-004","steps":["逐點極限都是 0。$f_n'(x)=\\frac{n(1-n^2x^2)}{(1+n^2x^2)^2}$：$x<\\frac{1}{n}$ 時遞增，$x>\\frac{1}{n}$ 時遞減。","$[0,1]$：取 $x_n=\\frac{1}{n}$，$f_n(x_n)=\\frac{1}{2}$，不趨近 0，不一致。","$[\\frac{1}{2},1]$：$n\\ge2$ 時 $\\frac{1}{n}\\le\\frac{1}{2}$，$f_n$ 在這段遞減，$\\|f_n\\|_\\infty=f_n(\\frac{1}{2})=\\frac{\\frac{n}{2}}{1+\\frac{n^2}{4}}=\\frac{2n}{4+n^2}\\to0$，一致收斂。"],"answer":"$[0,1]$ 上不一致；$[\\frac{1}{2},1]$ 上一致"},{"title":"用 Dini 定理","prompt":"$f_n(x)=(1+\\frac{x}{n})^n$ 在 $[0,1]$ 上收斂到 $e^x$。證明是一致的，並求 $n=10$ 時的 $\\|e^x-f_{10}\\|_\\infty$。","steps":["單調：$x\\ge0$ 時，對 1 與 $n$ 個 $(1+\\frac{x}{n})$ 用算幾不等式，$(1+\\frac{x}{n})^{n/(n+1)}\\le\\frac{1+n(1+\\frac{x}{n})}{n+1}=1+\\frac{x}{n+1}$，兩邊 $n+1$ 次方得 $f_n(x)\\le f_{n+1}(x)$。","$[0,1]$ 有界閉、$f_n$ 與 $e^x$ 連續、對 $n$ 單調，由 Dini 定理一致收斂。","誤差 $h(x)=e^x-(1+\\frac{x}{n})^n$，$h'(x)=e^x-(1+\\frac{x}{n})^{n-1}\\ge e^x-(1+\\frac{x}{n})^n\\ge0$（因為 $1+\\frac{x}{n}\\ge1$，且 $(1+\\frac{x}{n})^n\\le e^x$），所以最大在 $x=1$：$\\|h\\|_\\infty=e-(1+\\frac{1}{n})^n$。","$n=10$：$e-1.1^{10}\\approx2.71828-2.59374\\approx0.1245$。"],"answer":"一致收斂；$n=10$ 時 $\\|e^x-f_{10}\\|_\\infty=e-1.1^{10}\\approx0.1245$","note":"Dini 只告訴你「一致」，不告訴你速度；誤差的公式還是要自己算。"}],"pitfalls":["沒先求逐點極限就開始估 $\\|f_n-f\\|_\\infty$。","上界裡還留著 $x$（例如 $|f_n(x)|\\le\\frac{1}{nx}$），就宣稱一致收斂。上界必須與 $x$ 無關。","只代幾個固定的 $x$ 看到誤差 $\\to0$，就說一致。固定 $x$ 的檢查只能證逐點收斂。","用 Dini 時忘了檢查「極限連續」或「區間有界閉」。"],"voice":"edce2af9","sections":[{"title":"先問：收斂到誰","beats":[{"show":["一致收斂到「誰」？"],"note":"先固定 $x$ 求 $f(x)=\\lim f_n(x)$。","say":"一致收斂一定是收斂到某個函數。所以第一步永遠是：固定 x，先把逐點極限求出來。","t":[0,9240]},{"show":["沒有 $f$，就沒有 $\\|f_n-f\\|_\\infty$"],"say":"沒有極限函數，就沒有誤差可算；逐點極限不存在，一致收斂當然也不成立。","t":[9240,16968]},{"show":["算出來／估出來／否定"],"note":"有了 $f$，再挑工具。","say":"有了 f 之後，有三種工具：把最大誤差算出來、用上界估出來，或者找壞點否定它。","t":[16968,25488]}],"check":0},{"title":"估出來","beats":[{"show":["找與 $x$ 無關的 $a_n\\to0$","$|f_n(x)-f(x)|\\le a_n$"],"say":"不必算到精確，只要找到一個跟 x 無關、又趨近零的上界就夠了。","t":[25488,31824]},{"show":["$\\left|\\frac{\\sin(nx)}{n}\\right|\\le\\frac{1}{n}$"],"say":"最簡單的例子：sine n x 除以 n，絕對值不會超過 n 分之一，不管 x 是多少。","t":[31824,39456]},{"show":["$f_n(x)=\\frac{x}{1+nx^2}$，逐點 $\\to0$"],"say":"再看 x 除以一加 n x 平方。x 不是零時分母往無限大跑，逐點極限是零。","t":[39456,47520]},{"show":["$1+nx^2\\ge2\\sqrt{n}|x|$"],"note":"由 $(\\sqrt{n}|x|-1)^2\\ge0$。","say":"用一個平方大於等於零的小技巧，分母至少是二倍根號 n 乘 x 的絕對值。","t":[47520,54672]},{"show":["$|f_n(x)|\\le\\frac{1}{2\\sqrt{n}}$"],"note":"跟 $x$ 無關，在整條實數線上一致收斂。","say":"x 約掉了，上界是二倍根號 n 分之一，跟 x 無關又趨近零，所以一致收斂。","t":[54672,62208]}],"check":1},{"title":"壞點在哪裡","beats":[{"show":["否定：找 $x_n$，誤差不趨近 0"],"note":"常見的 $x_n$：$\\frac{1}{n}$、$\\frac{1}{\\sqrt{n}}$、$1-\\frac{1}{n}$。","say":"要證不一致，就找一串點，讓誤差停著不下去。通常就是高峰的位置。","t":[62208,70104]},{"show":["$\\frac{nx}{1+n^2x^2}$ 在 $[0,1]$：$f_n(\\frac{1}{n})=\\frac{1}{2}$"],"say":"n x 除以一加 n 平方 x 平方，在零到一，取 x 等於 n 分之一，值一直是二分之一，不一致。","t":[70104,78960]},{"show":["改成 $[\\frac{1}{2},1]$"],"note":"$n\\ge2$ 時高峰跑出定義域。","say":"壞事發生在零附近。把定義域改成二分之一到一，高峰就跑到外面去了。","t":[78960,86640]},{"show":["$\\|f_n\\|_\\infty=f_n(\\frac{1}{2})=\\frac{2n}{4+n^2}\\to0$"],"say":"這一段上函數遞減，最大在左端二分之一，算出來是四加 n 平方分之二 n，趨近零，一致收斂。","t":[86640,96168]}],"check":2},{"title":"Dini 定理","beats":[{"show":["$[a,b]$ 有界閉、$f_n$ 連續","$f$ 連續、$f_n(x)$ 對 $n$ 單調"],"note":"四個條件都成立 $\\Rightarrow$ 一致收斂。","say":"Dini 定理：有界閉區間、每個 f n 連續、極限也連續、而且每個點上對 n 單調，那就一致收斂。","t":[96168,105600]},{"show":["$x^n$ 在 $[0,1]$：缺「$f$ 連續」"],"say":"四個條件一個都不能少。x 的 n 次方在零到一，極限在一跳了，缺極限連續，不一致。","t":[105600,114768]},{"show":["$x^n$ 在 $[0,1)$：缺……？"],"note":"這時極限是 0，連續。","say":"那在零到一不含一呢？極限變成零，連續了，也單調，可是還是不一致。缺的是哪一個？","t":[114768,124920]}],"check":3},{"title":"證明：Dini 定理","proof":true,"of":4,"skeleton":"反證","beats":[{"show":["$g_n=f_n-f$：連續、$\\ge0$、遞減 $\\to0$"],"note":"不妨設 $f_n$ 遞減。","say":"策略：反證。看差 g n，它連續、非負、對 n 遞減而且趨近零。假設不一致，推出矛盾。","t":[124920,135720]},{"show":["每個 $n$ 取 $x_n$：$g_n(x_n)\\ge\\varepsilon_0$"],"note":"$\\|g_n\\|_\\infty$ 遞減；極值定理取得到。","why":{"ask":"為什麼每個 $n$ 都 $\\ge\\varepsilon_0$，不只某些 $n$？","say":"不一致，為什麼每一個 n 的最大誤差都至少 epsilon 零？","options":[{"label":"$\\|g_n\\|_\\infty$ 對 $n$ 遞減，不趨近 0 就停在上面","correct":true},{"label":"不一致收斂，就是每個 $n$ 都有壞點","why":"否定一致只給出無限多個 $n$ 誤差大；要每一個 $n$ 都大，靠的是 $\\|g_n\\|_\\infty$ 遞減。"},{"label":"因為 $g_n\\ge0$","why":"非負只說不會跑到負的；讓它一直停在 $\\varepsilon_0$ 以上的是遞減。"}],"t":[135720,140736]},"say":"最大誤差對 n 遞減，不趨近零，就一直停在某個 epsilon 零以上；極值定理給出取到最大的點。","t":[140736,149304]},{"show":["子數列 $x_{n_k}\\to x^*\\in[a,b]$"],"note":"Bolzano–Weierstrass；區間是閉的。","say":"這串點在有界閉區間裡，挑出收斂的子數列，極限 x 星還在區間裡。","t":[149304,156336]},{"show":["固定 $m$，$n_k\\ge m$ 時","$g_m(x_{n_k})\\ge g_{n_k}(x_{n_k})\\ge\\varepsilon_0$"],"note":"同一點上，$g_n$ 對 $n$ 遞減。","why":{"ask":"為什麼 $g_m(x_{n_k})\\ge g_{n_k}(x_{n_k})$？","say":"固定一個 m。在同一點，g m 為什麼不小於 g n k？","options":[{"label":"$m\\le n_k$，而每一點上 $g_n$ 對 $n$ 遞減","correct":true},{"label":"$g_m$ 連續","why":"連續要等下一步取極限才用；比較同一點、不同的 $n$，靠的是單調。"},{"label":"$x_{n_k}$ 是 $g_m$ 的最大值點","why":"$x_{n_k}$ 是 $g_{n_k}$ 取到大值的點，跟 $g_m$ 的最大值無關；這裡比的是同一點、不同的 $n$。"}],"t":[156336,162144]},"say":"m 不超過 n k，在同一點上 g 對 n 遞減，所以 g m 更大，也至少 epsilon 零。","t":[162144,169464]},{"show":["$k\\to\\infty$：$g_m(x^*)\\ge\\varepsilon_0$"],"note":"$g_m$ 連續。","say":"讓 k 趨近無限大，g m 連續，不等式留到極限點：g m 在 x 星至少 epsilon 零。","t":[169464,177264]},{"show":["每個 $m$ 都成立：與 $g_m(x^*)\\to0$ 矛盾"],"say":"這對每一個 m 都成立，可是 g m 在 x 星應該趨近零，矛盾。所以一致收斂。","t":[177264,185304]}],"order":{"ask":"把證明排回順序：依序點每一步","steps":[{"label":"反設：$\\|g_n\\|_\\infty\\ge\\varepsilon_0$ 對所有 $n$"},{"label":"取 $x_n$ 使 $g_n(x_n)\\ge\\varepsilon_0$","why":"要先有 $\\varepsilon_0$，才知道要找多大的值。"},{"label":"子數列 $x_{n_k}\\to x^*$","why":"要先有 $(x_n)$ 這串點，才能挑子數列。"},{"label":"固定 $m$，取極限：$g_m(x^*)\\ge\\varepsilon_0$","why":"要先有極限點 $x^*$，才能在那裡取極限。"},{"label":"與 $g_m(x^*)\\to0$ 矛盾","why":"要先知道每一個 $m$ 都有 $g_m(x^*)\\ge\\varepsilon_0$，才矛盾。"}]}},{"title":"用 Dini 證一致","beats":[{"show":["$f_n(x)=(1+\\frac{x}{n})^n\\to e^x$，$[0,1]$"],"say":"一加 n 分之 x 的 n 次方，在零到一收斂到 e 的 x 次方。是一致的嗎？","t":[185304,192384]},{"show":["$f_n(x)\\le f_{n+1}(x)$"],"note":"對 1 與 $n$ 個 $(1+\\frac{x}{n})$ 用算幾不等式。","say":"用算幾不等式，可以證明它對 n 遞增。區間有界閉、函數都連續，Dini 說：一致收斂。","t":[192384,201984]},{"show":["$h(x)=e^x-(1+\\frac{x}{n})^n$，$h'\\ge0$"],"note":"Dini 不給速度，誤差自己算。","say":"可是 Dini 不告訴你誤差多大。看誤差函數 h，它的導數大於等於零，所以誤差一路往右變大。","t":[201984,211608]}],"predict":{"ask":"$n=10$ 時 $\\|e^x-f_{10}\\|_\\infty$ 是？","options":[{"label":"$e-1.1^{10}\\approx0.1245$","correct":true},{"label":"0","why":"那是 $x=0$ 的誤差 $h(0)$；$h$ 遞增，最大在右端 $x=1$。"},{"label":"$e\\approx2.71828$","why":"那是 $e^x$ 在 $x=1$ 的值；誤差要再減掉 $f_{10}(1)=1.1^{10}\\approx2.59374$。"}]}}],"checks":[{"ask":"判斷 $f_n$ 是否一致收斂，第一步應該做什麼？","options":[{"label":"先固定 $x$ 求逐點極限 $f$","correct":true},{"label":"直接對 $f_n$ 微分找最大值","why":"你要的是 $|f_n-f|$ 的最大值，不是 $f_n$ 的。不先知道 $f$，算出來的 $\\sup$ 沒有意義（除非 $f\\equiv0$）。"},{"label":"檢查每個 $f_n$ 是否連續","why":"連續性只能拿來否定（極限不連續 $\\Rightarrow$ 不一致），不能當判斷的起點。"}]},{"ask":"$f_n(x)=\\frac{x}{1+nx^2}$ 在 $\\mathbb{R}$ 上，$\\|f_n\\|_\\infty$ 是？","options":[{"label":"$\\frac{1}{2\\sqrt{n}}$","correct":true},{"label":"$\\frac{1}{n}$","why":"你可能代了 $x=1$：$\\frac{1}{1+n}$，大約 $\\frac{1}{n}$。最大值在 $x=\\frac{1}{\\sqrt{n}}$，不在 $x=1$。"},{"label":"$\\infty$","why":"分子 $x$ 變大時分母 $nx^2$ 變得更快，$f_n$ 有界。由 $1+nx^2\\ge2\\sqrt{n}|x|$ 可得上界 $\\frac{1}{2\\sqrt{n}}$。"}]},{"ask":"$f_n(x)=\\frac{nx}{1+n^2x^2}$ 在 $[\\frac{1}{2},1]$ 上，下列何者正確？","options":[{"label":"一致收斂，因為 $n\\ge2$ 時 $\\|f_n\\|_\\infty=\\frac{2n}{4+n^2}\\to0$","correct":true},{"label":"不一致，因為 $f_n(\\frac{1}{n})=\\frac{1}{2}$","why":"你沿用了 $[0,1]$ 的論證。$n\\ge3$ 時 $\\frac{1}{n}<\\frac{1}{2}$，$x_n=\\frac{1}{n}$ 根本不在 $[\\frac{1}{2},1]$ 裡。"},{"label":"不一致，因為高峰的高度一直是 $\\frac{1}{2}$","why":"高峰在 $x=\\frac{1}{n}$，已經跑出 $[\\frac{1}{2},1]$。這段區間上 $f_n$ 是遞減的，最大在 $x=\\frac{1}{2}$。"}]},{"ask":"$x^n$ 在 $[0,1)$ 上單調遞減到連續的 0，每個 $x^n$ 也連續，卻不一致收斂。它違反 Dini 定理的哪個條件？","options":[{"label":"定義域不是有界閉區間","correct":true},{"label":"極限函數不連續","why":"在 $[0,1)$ 上極限是 0，連續。不連續是 $[0,1]$ 那個例子的問題。"},{"label":"$f_n(x)$ 對 $n$ 不單調","why":"$0\\le x<1$ 時 $x^{n+1}\\le x^n$，是單調的。"}]}],"practice":[{"id":"an-uf-002","core":true},{"id":"an-uf-004","core":true},{"id":"an-uf-001","core":true},{"id":"an-uf-003","core":true},{"id":"an-uf-005","challenge":true,"note":"挑戰：高峰位置 $\\frac{1}{\\sqrt{2n}}$ 就是要找的 $x_n$。"}]},"weierstrass-m-test":{"id":"weierstrass-m-test","prerequisites":["uniform-convergence-tests","cauchy-sequence","comparison-test"],"next":["limit-integral-swap"],"related":["power-series","radius-of-convergence","power-series-calculus","limit-derivative-swap"],"objectives":["把函數項級數 $\\sum u_n(x)$ 的一致收斂，讀成部分和 $S_n(x)$ 的一致收斂。","用 $M$ 判別：找與 $x$ 無關的 $M_n\\ge|u_n(x)|$，且 $\\sum M_n$ 收斂，就得到絕對且一致收斂。","說明冪級數在收斂半徑內的每個閉區間 $[-r,r]$ 上一致收斂。"],"concept":[{"heading":"① 函數項級數就是一列部分和","body":["$\\sum u_n(x)$ 收斂到 $S(x)$，指的是部分和 $S_n(x)=u_1(x)+\\dots+u_n(x)$ 收斂到 $S(x)$。一致收斂也一樣：$S_n$ 在 $D$ 上一致收斂到 $S$。","直接算 $\\|S_n-S\\|_\\infty$ 通常做不到，因為 $S$ 沒有公式。所以需要一個不必知道 $S$ 的判別法。"]},{"heading":"② $M$ 判別","body":["若存在數 $M_n$，使 $|u_n(x)|\\le M_n$ 對所有 $x\\in D$ 與所有 $n$ 成立，而且數字級數 $\\sum M_n$ 收斂，則 $\\sum u_n(x)$ 在 $D$ 上絕對收斂而且一致收斂。","直覺，不是證明：每一項都被一個不看 $x$ 的數蓋住，所以尾巴 $\\sum_{k>n}|u_k(x)|$ 也被 $\\sum_{k>n} M_k$ 蓋住；後者是收斂級數的尾巴，會 $\\to0$，而且跟 $x$ 無關。缺的那一步是：沒有 $S$ 的公式，怎麼從「尾巴一致地小」得到一致收斂——這要靠一致 Cauchy 準則（下方證明）。","搭配上一章：若每個 $u_n$ 連續，和函數 $S$ 也連續。"],"tex":["|u_n(x)|\\le M_n\\ \\ (\\forall x\\in D),\\quad \\sum M_n<\\infty\\ \\Longrightarrow\\ \\sum u_n\\ \\text{在 }D\\text{ 上一致收斂}"]},{"heading":"③ 冪級數","body":["$\\sum a_nx^n$ 的收斂半徑是 $R$，$0<r<R$。在 $[-r,r]$ 上 $|a_nx^n|\\le|a_n|r^n=M_n$，而 $\\sum|a_n|r^n$ 收斂（$r$ 在收斂半徑內，絕對收斂）。所以冪級數在每個 $[-r,r]$ 上一致收斂，和函數在 $(-R,R)$ 上連續。整個 $(-R,R)$ 上則不一定一致（範例 2）。"]},{"heading":"證明：一致 Cauchy 準則與 $M$ 判別","body":["一致 Cauchy 準則：$f_n$ 在 $D$ 上一致收斂，若且唯若對每個 $\\varepsilon>0$ 存在 $N$，使所有 $m,n\\ge N$ 與所有 $x\\in D$ 都有 $|f_n(x)-f_m(x)|<\\varepsilon$。","（$\\Rightarrow$）取 $N$ 使 $n\\ge N$ 時 $|f_n(x)-f(x)|<\\frac{\\varepsilon}{2}$ 對所有 $x$ 成立，再用三角不等式。（$\\Leftarrow$）固定 $x$，$f_n(x)$ 是實數的 Cauchy 數列，由實數完備性收斂，記為 $f(x)$。固定 $n\\ge N$ 與 $x$，在 $|f_n(x)-f_m(x)|<\\varepsilon$ 中令 $m\\to\\infty$，得 $|f_n(x)-f(x)|\\le\\varepsilon$；$N$ 與 $x$ 無關，所以一致收斂。","$M$ 判別：$m>n$ 時，$|S_m(x)-S_n(x)|\\le\\sum_{k=n+1}^{m}|u_k(x)|\\le\\sum_{k=n+1}^{m} M_k\\le\\sum_{k>n} M_k$。$\\sum M_k$ 收斂，尾巴 $\\to0$：給 $\\varepsilon$ 取 $N$ 使 $\\sum_{k>N} M_k<\\varepsilon$，則 $m>n\\ge N$ 時對所有 $x$ 都有 $|S_m(x)-S_n(x)|<\\varepsilon$。由準則，$S_n$ 一致收斂。絕對收斂則是逐點的比較判別。"],"collapsible":true},{"heading":"$M$ 判別只是充分條件","body":["$\\sum(-1)^{n+1}\\frac{x^n}{n}$ 在 $[0,1]$ 上一致收斂：交錯級數的誤差 $\\le\\frac{x^{n+1}}{n+1}\\le\\frac{1}{n+1}$，與 $x$ 無關。但 $\\sup|u_n(x)|=\\frac{1}{n}$，$\\sum\\frac{1}{n}$ 發散，$M$ 判別用不上。找不到 $M_n$ 不代表不一致。"],"collapsible":true}],"workedExamples":[{"title":"三角級數","prompt":"證明 $\\sum_{n=1}^\\infty\\frac{\\sin(nx)}{n^2}$ 在 $\\mathbb{R}$ 上一致收斂，和函數連續，且 $|S(x)|\\le\\frac{\\pi^2}{6}$。","steps":["對所有 $x$，$|\\frac{\\sin(nx)}{n^2}|\\le\\frac{1}{n^2}$。取 $M_n=\\frac{1}{n^2}$，它與 $x$ 無關。","$\\sum\\frac{1}{n^2}$ 收斂（$p$ 級數，$p=2>1$），而且 $\\sum\\frac{1}{n^2}=\\frac{\\pi^2}{6}$。由 $M$ 判別，級數在 $\\mathbb{R}$ 上絕對且一致收斂。","每一項 $\\frac{\\sin(nx)}{n^2}$ 連續，部分和連續，一致極限 $S$ 連續。","$|S(x)|\\le\\sum|\\sin(nx)|/n^2\\le\\sum\\frac{1}{n^2}=\\frac{\\pi^2}{6}$。"],"answer":"一致收斂、$S$ 連續、$|S(x)|\\le\\frac{\\pi^2}{6}$"},{"title":"幾何級數：閉區間一致、開區間不一致","prompt":"$\\sum_{k=1}^\\infty x^k$。(a) 在 $[-0.9,0.9]$ 上一致收斂嗎？要讓尾巴 $\\sum_{k>n} 0.9^k<0.01$，$n$ 至少多少？(b) 在 $(-1,1)$ 上呢？","steps":["(a) $|x^k|\\le0.9^k=M_k$，$\\sum0.9^k$ 收斂，$M$ 判別給出一致收斂。","尾巴：$\\sum_{k=n+1}^\\infty0.9^k=\\frac{0.9^{n+1}}{1-0.9}=10\\cdot0.9^{n+1}$。$n=64$ 時 $10\\cdot0.9^{65}\\approx0.0106$，$n=65$ 時 $10\\cdot0.9^{66}\\approx0.0086$，所以 $n$ 至少 65。這個 $n$ 對區間上每一個 $x$ 都有效。","(b) 在 $(-1,1)$ 上，和是 $\\frac{x}{1-x}$，誤差 $S(x)-S_n(x)=\\frac{x^{n+1}}{1-x}$。$x\\to1^-$ 時它 $\\to\\infty$，所以 $\\sup$ 是 $\\infty$，對每個 $n$ 都不趨近 0，不一致收斂。"],"answer":"(a) 一致，$n\\ge65$；(b) 不一致"},{"title":"端點也能一致","prompt":"$\\sum_{n=1}^\\infty\\frac{x^n}{n^2}$ 的收斂半徑是 1。證明它在閉區間 $[-1,1]$（含端點）上一致收斂。","steps":["$|x|\\le1$ 時 $|\\frac{x^n}{n^2}|\\le\\frac{1}{n^2}$。$M_n=\\frac{1}{n^2}$ 與 $x$ 無關，$\\sum\\frac{1}{n^2}$ 收斂。","由 $M$ 判別，在 $[-1,1]$ 上一致收斂，和函數在 $[-1,1]$ 上連續，包括兩個端點。","兩端的值：$x=1$ 時是 $\\sum\\frac{1}{n^2}=\\frac{\\pi^2}{6}$，$x=-1$ 時是 $\\sum\\frac{(-1)^n}{n^2}=-\\frac{\\pi^2}{12}$。"],"answer":"在 $[-1,1]$ 上一致收斂；$S(1)=\\frac{\\pi^2}{6}$，$S(-1)=-\\frac{\\pi^2}{12}$","note":"對比範例 2：$\\sum x^k$ 的 $M_k$ 在 $r\\to1$ 時變成 1，$\\sum1$ 發散，所以端點附近失守。"}],"pitfalls":["$M_n$ 裡還有 $x$（例如取 $M_n=|x|^n$）。$M_n$ 必須是只跟 $n$ 有關的數。","$M_n$ 選得太鬆，$\\sum M_n$ 發散，就斷言級數不一致收斂。$M$ 判別只是充分條件。","以為冪級數在整個收斂區間上都一致收斂。保證的是每個 $[-r,r]$（$r<R$）。","用 $M$ 判別證完一致收斂，就說和函數可微。可微要看導數級數（〈極限與微分交換〉）。"],"voice":"575fb4b2","sections":[{"title":"級數是一列部分和","beats":[{"show":["$S_n(x)=u_1(x)+\\dots+u_n(x)$"],"say":"函數項級數收斂，意思是它的部分和收斂。一致收斂也一樣，看部分和是不是一致收斂。","t":[0,9456]},{"show":["$S_n\\to S$ 一致？"],"note":"$S$ 通常沒有公式。","say":"問題是和函數 S 通常寫不出公式，最大誤差根本沒辦法直接算。","t":[9456,16056]}],"predict":{"ask":"那我們需要什麼樣的判別法？","options":[{"label":"不必知道 $S$ 的判別法","correct":true},{"label":"先求出 $S$ 的公式","why":"大多數級數的和沒有公式，這條路通常走不通。"},{"label":"代幾個 $x$ 看部分和有沒有收斂","why":"固定 $x$ 只能檢查逐點收斂，看不出一致。"}]}},{"title":"$M$ 判別","beats":[{"show":["$|u_n(x)|\\le M_n$（所有 $x$）","$\\sum M_n<\\infty$"],"say":"M 判別：每一項都被一個不看 x 的數 M n 蓋住，而且這些數加起來收斂。","t":[16056,23160]},{"show":["$\\Rightarrow\\sum u_n$ 在 $D$ 上一致收斂"],"note":"而且絕對收斂。","say":"那函數項級數就在整個定義域上絕對收斂，而且一致收斂。","t":[23160,29280]},{"show":["尾巴 $\\le\\sum_{k>n}M_k\\to0$"],"note":"跟 $x$ 無關。","say":"為什麼？尾巴被 M 的尾巴蓋住，那是收斂級數的尾巴，會趨近零，而且跟 x 無關。證明在下一節。","t":[29280,40104]},{"show":["每個 $u_n$ 連續 $\\Rightarrow S$ 連續"],"say":"再接上一章：每一項都連續，和函數也連續。","t":[40104,45120]}],"check":1},{"title":"證明：用 Cauchy 準則","proof":true,"of":3,"skeleton":"ε-δ","beats":[{"show":["不跟 $S$ 比：部分和彼此比"],"note":"一致 Cauchy 準則。","say":"策略：和函數 S 不知道，就不跟 S 比，改成部分和彼此比，用一致 Cauchy 準則。","t":[45120,53112]},{"show":["$|S_m(x)-S_n(x)|\\le\\sum_{k=n+1}^{m}|u_k(x)|$"],"note":"$m>n$，三角不等式。","say":"兩個部分和相減，剩下第 n 加一項到第 m 項；三角不等式，拆成每一項的絕對值。","t":[53112,61392]},{"show":["$\\le\\sum_{k=n+1}^{m}M_k\\le\\sum_{k>n}M_k$"],"note":"每一項 $|u_k(x)|\\le M_k$。","why":{"ask":"為什麼這個上界跟 $x$ 無關？","say":"這個上界裡已經沒有 x 了。為什麼可以甩掉 x？","options":[{"label":"$M_k$ 對所有 $x$ 都蓋得住 $|u_k(x)|$","correct":true},{"label":"$\\sum u_k$ 絕對收斂","why":"絕對收斂是逐點的：每個 $x$ 的尾巴各自變小，不保證一起小。甩掉 $x$ 靠的是 $M_k$ 不看 $x$。"},{"label":"每個 $u_k$ 都連續，所以有界","why":"連續函數在 $D$ 上不一定有界；就算有界，界也是各管各的。這裡靠的是給定的 $M_k$。"}],"t":[61392,66816]},"say":"每一項都被不看 x 的 M k 蓋住，所以整段被 M 的尾巴蓋住，跟 x 無關。","t":[66816,73584]},{"show":["取 $N$：$\\sum_{k>N}M_k<\\varepsilon$"],"note":"$\\sum M_k$ 收斂，尾巴 $\\to0$。","why":{"ask":"為什麼找得到這樣的 $N$？","say":"給定 epsilon，這個 N 為什麼找得到？","options":[{"label":"$\\sum M_k$ 收斂，尾巴趨近 0","correct":true},{"label":"$M_k\\to0$","why":"項趨近 0 不夠：$\\sum\\frac{1}{k}$ 的項趨近 0，尾巴卻一直是無限大。"},{"label":"每個 $x$ 的 $|u_k(x)|$ 都很小","why":"那是逐點的；$N$ 要對所有 $x$ 一起有效，只能從 $M_k$ 的尾巴找。"}],"t":[73584,77280]},"say":"M 的級數收斂，尾巴趨近零，所以取得到 N，讓 N 以後的尾巴小於 epsilon。","t":[77280,84336]},{"show":["$m>n\\ge N$：$|S_m(x)-S_n(x)|<\\varepsilon$，$\\forall x$"],"note":"由準則：$S_n$ 一致收斂。","say":"於是 m 大於 n 大於等於 N 時，對所有 x，部分和的差都小於 epsilon。由準則，一致收斂。","t":[84336,93504]}],"where":{"ask":"「$\\sum M_k$ 收斂」用在哪一步？","steps":[{"label":"三角不等式：$|S_m-S_n|\\le\\sum|u_k|$","why":"這只用到三角不等式，任何級數都成立。"},{"label":"$\\le\\sum_{k>n}M_k$","why":"這只用到 $|u_k(x)|\\le M_k$；就算 $\\sum M_k$ 發散，不等式也成立，只是右邊是無限大。"},{"label":"取 $N$ 使 $\\sum_{k>N}M_k<\\varepsilon$","correct":true},{"label":"由一致 Cauchy 準則推出一致收斂","why":"準則本身靠的是實數的完備性，跟 $M_k$ 無關。"}]}},{"title":"三角級數","beats":[{"show":["$\\sum_{n=1}^\\infty\\frac{\\sin(nx)}{n^2}$"],"say":"來用一次：sine n x 除以 n 平方，從一加到無限大，在整條實數線上。","t":[93504,100800]},{"show":["$\\left|\\frac{\\sin(nx)}{n^2}\\right|\\le\\frac{1}{n^2}=M_n$"],"say":"sine 的絕對值不超過一，所以每一項被 n 平方分之一蓋住，這個數跟 x 無關。","t":[100800,108096]},{"show":["$\\sum\\frac{1}{n^2}=\\frac{\\pi^2}{6}$ 收斂"],"note":"$p$ 級數，$p=2>1$。","say":"n 平方分之一加起來收斂，等於六分之 pi 平方。M 判別說：一致收斂。","t":[108096,115896]},{"show":["$S$ 連續，$|S(x)|\\le\\frac{\\pi^2}{6}$"],"say":"每一項連續，所以和函數連續；而且它的絕對值不會超過六分之 pi 平方。","t":[115896,123216]}],"check":0},{"title":"幾何級數的尾巴","beats":[{"show":["$\\sum x^k$ 在 $[-0.9,0.9]$"],"note":"$|x^k|\\le0.9^k=M_k$。","say":"幾何級數 x 的 k 次方，限制在負零點九到零點九，每一項被零點九的 k 次方蓋住。","t":[123216,131088]},{"show":["$\\sum_{k>n}0.9^k=\\frac{0.9^{n+1}}{1-0.9}$","$=10\\cdot0.9^{n+1}$"],"say":"零點九的幾何級數收斂，所以一致收斂。它的尾巴是十倍的零點九的 n 加一次方。","t":[131088,139512]},{"show":["要尾巴 $<0.01$：$n$ 至少多少？"],"note":"這個 $n$ 對區間上每個 $x$ 都有效。","say":"要讓尾巴小於零點零一，n 至少要多少？算出來的 n，對區間上每一個 x 同時有效。","t":[139512,148320]}],"check":3},{"title":"開區間失守","beats":[{"show":["冪級數：在每個 $[-r,r]$ 一致"],"note":"$0<r<R$，$|a_nx^n|\\le|a_n|r^n$。","say":"同樣的道理，冪級數在收斂半徑裡面的每個閉區間上，都一致收斂。","t":[148320,154944]},{"show":["$\\sum x^k$ 在 $(-1,1)$：誤差 $\\frac{x^{n+1}}{1-x}$"],"say":"可是整個負一到一呢？和是一減 x 分之 x，誤差是 x 的 n 加一次方除以一減 x。","t":[154944,162984]},{"show":["$x\\to1^-$：誤差 $\\to\\infty$"],"note":"$M_k$ 在 $r\\to1$ 時變成 1，$\\sum1$ 發散。","say":"x 從左邊靠近一，分母趨近零，誤差衝到無限大，對每個 n 都一樣。","t":[162984,170016]}],"check":2},{"title":"端點也能一致","beats":[{"show":["$\\sum_{n=1}^\\infty\\frac{x^n}{n^2}$，收斂半徑 1"],"say":"換成 x 的 n 次方除以 n 平方，收斂半徑也是一。它在端點也守得住嗎？","t":[170016,177720]},{"show":["在 $[-1,1]$ 上，含端點"],"note":"$|x|\\le1$。","say":"這次直接看負一到一的閉區間，連兩個端點都算進來，找一個蓋得住的 M n。","t":[177720,184920]}],"predict":{"ask":"在 $[-1,1]$ 上合用的 $M_n$ 是？","options":[{"label":"$\\frac{1}{n^2}$：$\\sum M_n$ 收斂，一致","correct":true},{"label":"$\\frac{|x|^n}{n^2}$","why":"$M_n$ 裡還有 $x$。$M_n$ 必須只跟 $n$ 有關；$|x|\\le1$ 讓你換成 $\\frac{1}{n^2}$。"},{"label":"1：$\\sum1$ 發散，所以不一致","why":"$M_n$ 取太鬆，$M$ 判別推不出東西，但不代表不一致。$\\frac{1}{n^2}$ 就蓋得住。"}]}}],"checks":[{"ask":"對 $\\sum\\frac{\\sin(nx)}{n^2}$（$x\\in\\mathbb{R}$），哪一個是合用的 $M_n$？","options":[{"label":"$\\frac{1}{n^2}$","correct":true},{"label":"$\\frac{\\sin(n)}{n^2}$","why":"你代了 $x=1$。$M_n$ 要對所有 $x$ 都蓋得住 $|u_n(x)|$，而且不能是負的。"},{"label":"$\\frac{1}{n}$","why":"$\\frac{1}{n}$ 確實 $\\ge|\\frac{\\sin(nx)}{n^2}|$，但 $\\sum\\frac{1}{n}$ 發散，$M$ 判別就什麼都推不出來。"}]},{"ask":"$M$ 判別的結論是什麼？","options":[{"label":"級數在 $D$ 上絕對收斂而且一致收斂","correct":true},{"label":"級數的和函數可微","why":"你把一致收斂跟可微混在一起了。$M$ 判別只講級數本身；可微要對導數級數另外檢查。"},{"label":"級數在 $D$ 上逐點收斂，但不一定一致","why":"$M_n$ 與 $x$ 無關，尾巴的估計對所有 $x$ 同時成立，所以結論正是一致收斂。"}]},{"ask":"$\\sum x^k$ 在 $(-1,1)$ 上：","options":[{"label":"逐點收斂，但不一致收斂","correct":true},{"label":"一致收斂，因為在每個 $[-r,r]$ 上都一致","why":"在每個閉子區間上一致，不等於在整個 $(-1,1)$ 上一致；誤差 $\\frac{x^{n+1}}{1-x}$ 在 $x\\to1^-$ 時沒有上界。"},{"label":"連逐點收斂都不成立","why":"$|x|<1$ 時幾何級數收斂。出問題的只是收斂的速度不能一致。"}]},{"ask":"在 $[-0.9,0.9]$ 上要讓 $\\sum_{k>n} 0.9^k<0.01$，最小的 $n$ 是？","options":[{"label":"65","correct":true},{"label":"44","why":"你解的是 $0.9^n<0.01$，漏了尾巴的係數：$\\sum_{k>n} 0.9^k=10\\cdot0.9^{n+1}$。"},{"label":"66","why":"你解出 $n+1\\ge66$ 之後忘了減 1。$n=65$ 時尾巴 $10\\cdot0.9^{66}\\approx0.0086$ 已經夠小。"}]}],"practice":[{"id":"exam-ser-001","core":true,"note":"求出 $R$ 之後想一想：$M$ 判別保證在哪些區間上一致收斂？"},{"id":"exam-ser-003","core":true},{"id":"lec-14-m3","note":"$R=\\infty$：在每個有界區間 $[-r,r]$ 上取 $M_n=\\frac{r^n}{n!}$。"}]},"limit-integral-swap":{"id":"limit-integral-swap","prerequisites":["weierstrass-m-test","uniform-convergence","uniform-convergence-tests"],"next":["limit-derivative-swap"],"related":["pointwise-convergence","riemann-integrability","dominated-convergence","monotone-convergence-theorem"],"objectives":["證明並使用：連續函數列在 $[a,b]$ 上一致收斂時，$\\lim\\int_a^b f_n=\\int_a^b\\lim f_n$。","用 $M$ 判別加上這個定理，合法地逐項積分一個函數項級數。","對每個條件舉出反例：不一致時會壞、區間無界時也會壞。"],"concept":[{"heading":"① 問題","body":["$f_n\\to f$ 時，$\\lim\\int f_n$ 會不會等於 $\\int f$？〈逐點收斂〉那一課看過不會：$nx e^{-nx^2}$ 在 $[0,1]$ 上逐點收斂到 0，積分卻趨近 $\\frac{1}{2}$。高峰把面積「藏」在一個越來越窄的地方，逐點收斂看不見它。"]},{"heading":"② 定理與證明","body":["定理：若每個 $f_n$ 在 $[a,b]$ 上連續，且 $f_n$ 在 $[a,b]$ 上一致收斂到 $f$，則 $f$ 連續（所以可積），而且 $\\lim\\int_a^b f_n\\,dx=\\int_a^b f\\,dx$。","證明只有一行：$|\\int_a^b f_n-\\int_a^b f|\\le\\int_a^b|f_n-f|\\le(b-a)\\|f_n-f\\|_\\infty\\to0$。$f$ 連續是上一章的定理。","用到兩件事：誤差有一個與 $x$ 無關的上界 $\\|f_n-f\\|_\\infty$（一致性），以及區間長度 $b-a$ 有限。"],"tex":["\\left|\\int_a^b f_n-\\int_a^b f\\right|\\le (b-a)\\,\\|f_n-f\\|_\\infty"]},{"heading":"③ 級數版：逐項積分","body":["若 $\\sum u_n$ 在 $[a,b]$ 上一致收斂（例如由 $M$ 判別），每個 $u_n$ 連續，則 $\\int_a^b\\sum u_n=\\sum\\int_a^b u_n$。理由：有限和本來就能和積分交換，把定理套在部分和 $S_n$ 上即可。"]},{"heading":"④ 條件拿掉會怎樣","body":["不一致：$nx e^{-nx^2}$，$\\lim\\int_0^1=\\frac{1}{2}$，$\\int_0^1\\lim=0$。","區間無界：$(\\frac{1}{n})e^{-x/n}$ 在 $[0,\\infty)$ 上一致收斂到 0（$\\|f_n\\|_\\infty=\\frac{1}{n}$），但 $\\int_0^\\infty=1$ 對每個 $n$ 成立（範例 3）。$(b-a)\\|f_n-f\\|_\\infty$ 這個上界在 $b=\\infty$ 時失效。"]},{"heading":"預告：更一般的版本","body":["$f_n$ 只要 Riemann 可積（不必連續），一致收斂下極限 $f$ 仍然可積，而且積分可交換；證明要用上和、下和，見〈Riemann 可積〉。","一致收斂其實是很強的要求。Lebesgue 積分裡的〈控制收斂定理〉只要逐點收斂（甚至幾乎處處）加上一個可積的控制函數 $|f_n|\\le g$，就能交換，而且區間可以無界。"],"collapsible":true}],"workedExamples":[{"title":"先證一致，再交換","prompt":"求 $\\lim_{n\\to\\infty}\\int_0^1(1+\\frac{x}{n})^n\\,dx$。","steps":["〈怎麼判斷一致收斂〉的範例 3 用 Dini 定理證過：$(1+\\frac{x}{n})^n$ 在 $[0,1]$ 上一致收斂到 $e^x$，而且每個 $f_n$ 連續。","由定理，$\\lim\\int_0^1(1+\\frac{x}{n})^n\\,dx=\\int_0^1 e^x\\,dx=e-1\\approx1.718$。","直接算也對得上：$\\int_0^1(1+\\frac{x}{n})^n\\,dx=(\\frac{n}{n+1})[(1+\\frac{1}{n})^{n+1}-1]$，$n\\to\\infty$ 時 $\\to e-1$。"],"answer":"$e-1$"},{"title":"逐項積分","prompt":"利用 $\\frac{1}{1-x}=\\sum_{n=0}^\\infty x^n$，求 $\\sum_{k=1}^\\infty\\frac{1}{k\\cdot2^k}$。","problemId":"lec-14-q3c","steps":["在 $[0,\\frac{1}{2}]$ 上 $|x^n|\\le(\\frac{1}{2})^n$，$\\sum(\\frac{1}{2})^n$ 收斂，由 $M$ 判別 $\\sum x^n$ 一致收斂，每一項連續，可以逐項積分。","左邊：$\\int_0^{1/2}\\frac{1}{1-x}\\,dx=[-\\ln(1-x)]_0^{1/2}=\\ln2$。","右邊：$\\sum_{n=0}^\\infty\\int_0^{1/2} x^n\\,dx=\\sum_{n=0}^\\infty\\frac{(\\frac{1}{2})^{n+1}}{n+1}$，令 $k=n+1$ 得 $\\sum_{k=1}^\\infty\\frac{1}{k\\cdot2^k}$。","所以 $\\sum\\frac{1}{k\\cdot2^k}=\\ln2$。"],"answer":"$\\ln2$"},{"title":"一致收斂，積分卻不收斂到 0","prompt":"$f_n(x)=(\\frac{1}{n})e^{-x/n}$，$x\\in[0,\\infty)$。求 $\\|f_n\\|_\\infty$ 與 $\\int_0^\\infty f_n\\,dx$。","steps":["$f_n$ 遞減，最大值在 $x=0$：$\\|f_n-0\\|_\\infty=\\frac{1}{n}\\to0$，所以在 $[0,\\infty)$ 上一致收斂到 0。","$\\int_0^\\infty(\\frac{1}{n})e^{-x/n}\\,dx$：令 $u=\\frac{x}{n}$，$=\\int_0^\\infty e^{-u}\\,du=1$，對每個 $n$ 都是 1。","$\\lim\\int f_n=1\\ne0=\\int\\lim f_n$。一致收斂救不了無界區間：面積被攤到越來越遠的地方。"],"answer":"$\\|f_n\\|_\\infty=\\frac{1}{n}$，$\\int_0^\\infty f_n=1$"}],"pitfalls":["只有逐點收斂就把 $\\lim$ 搬進積分號。","在無界區間（或瑕積分）上以為一致收斂就夠。","逐項積分前沒說明級數在積分區間上一致收斂；冪級數要確認積分區間落在收斂半徑內的閉區間。","把 $\\int$ 的誤差上界寫成 $\\|f_n-f\\|_\\infty$，漏了區間長度 $b-a$。"],"voice":"e5b80c16","sections":[{"title":"積分會被藏起來","beats":[{"show":["$\\lim\\int f_n\\overset{?}{=}\\int f$"],"say":"函數列收斂了，積分的極限會不會等於極限的積分？","t":[0,5136]},{"show":["$nx e^{-nx^2}$ 在 $[0,1]$：逐點 $\\to0$"],"note":"積分卻趨近 $\\frac{1}{2}$。","say":"看過反例：n x 乘 e 的負 n x 平方，逐點收斂到零，積分卻趨近二分之一。","t":[5136,12744]},{"show":["高峰越來越窄，面積還在"],"say":"高峰把面積藏在越來越窄的地方，每個固定的點都看不見它，所以逐點收斂抓不到。","t":[12744,20592]}],"check":1},{"title":"一致收斂就能交換","beats":[{"show":["$f_n$ 連續、在 $[a,b]$ 一致收斂到 $f$"],"note":"$f$ 連續，所以可積。","say":"定理：每個 f n 在 a 到 b 上連續，又一致收斂到 f，那極限和積分就可以交換。","t":[20592,28392]},{"show":["$\\left|\\int_a^b f_n-\\int_a^b f\\right|\\le (b-a)\\,\\|f_n-f\\|_\\infty$"],"say":"證明只有一行：積分的差，不超過區間長度乘上最大誤差。最大誤差趨近零，就收工。","t":[28392,37608]},{"show":["用到兩件事：一致、區間有限"],"say":"注意它用了兩件事：誤差有一個跟 x 無關的上界，還有區間長度 b 減 a 是有限的。","t":[37608,45408]}],"check":0},{"title":"先證一致，再交換","beats":[{"show":["$\\lim_{n\\to\\infty}\\int_0^1(1+\\frac{x}{n})^n\\,dx$"],"say":"求積分從零到一，一加 n 分之 x 的 n 次方，n 趨近無限大的極限。","t":[45408,51888]},{"show":["Dini：在 $[0,1]$ 上一致收斂到 $e^x$"],"note":"每個 $f_n$ 連續。","say":"上一課用 Dini 定理證過，它在零到一上一致收斂到 e 的 x 次方，而且每一項都連續。","t":[51888,59832]}],"predict":{"ask":"所以極限是？","options":[{"label":"$\\int_0^1 e^x\\,dx=e-1\\approx1.718$","correct":true},{"label":"$e$","why":"$e$ 是 $e^x$ 在 $x=1$ 的值；交換後要積分：$\\int_0^1 e^x\\,dx=e-1$。"},{"label":"1","why":"那是 $n=1$ 附近的直覺。交換之後算 $\\int_0^1 e^x\\,dx=e-1$。"}]}},{"title":"逐項積分","beats":[{"show":["$\\int_a^b\\sum u_n=\\sum\\int_a^b u_n$"],"note":"條件：一致收斂、每項連續。","say":"級數版：一致收斂、每一項連續，就可以一項一項積分。理由是把定理套在部分和上。","t":[59832,69096]},{"show":["$\\frac{1}{1-x}=\\sum_{n=0}^\\infty x^n$，在 $[0,\\frac{1}{2}]$"],"note":"$|x^n|\\le(\\frac{1}{2})^n$，$M$ 判別。","say":"拿一減 x 分之一的幾何級數，在零到二分之一上，用 M 判別知道它一致收斂。","t":[69096,76560]},{"show":["左邊：$\\int_0^{1/2}\\frac{1}{1-x}\\,dx=\\ln2$"],"say":"左邊積出來是負的自然對數一減 x，從零到二分之一，等於自然對數二。","t":[76560,83688]},{"show":["右邊：$\\sum_{n=0}^\\infty\\frac{(\\frac{1}{2})^{n+1}}{n+1}$"],"note":"令 $k=n+1$。","say":"右邊每一項積出來，是二分之一的 n 加一次方，再除以 n 加一。兩邊相等。","t":[83688,91632]}],"check":3},{"title":"區間無界就不行","beats":[{"show":["$f_n(x)=(\\frac{1}{n})e^{-x/n}$，$[0,\\infty)$"],"say":"最後一個：n 分之一乘 e 的負 n 分之 x，在零到無限大上。","t":[91632,97536]},{"show":["$\\|f_n\\|_\\infty=\\frac{1}{n}\\to0$"],"note":"最大值在 $x=0$，一致收斂到 0。","say":"函數遞減，最大值在零，是 n 分之一，趨近零。所以它一致收斂到零。","t":[97536,105600]},{"show":["$\\int_0^\\infty f_n\\,dx=1$"],"note":"令 $u=\\frac{x}{n}$。","say":"可是積分換個變數，對每個 n 都是一。面積被攤平，攤到越來越遠的地方。","t":[105600,113544]}],"check":2}],"checks":[{"ask":"證明 $\\int_a^b f_n\\to\\int_a^b f$ 的關鍵不等式是？","options":[{"label":"$|\\int_a^b f_n-\\int_a^b f|\\le(b-a)\\|f_n-f\\|_\\infty$","correct":true},{"label":"$|\\int_a^b f_n-\\int_a^b f|\\le\\|f_n-f\\|_\\infty$","why":"你漏了區間長度。被積函數的上界要乘上 $b-a$ 才是積分的上界。"},{"label":"$|\\int_a^b f_n-\\int_a^b f|\\le|f_n(a)-f(a)|(b-a)$","why":"你只看一個點的誤差。要控制整段，需要所有 $x$ 共用的上界，也就是 $\\sup$。"}]},{"ask":"$f_n(x)=nx e^{-nx^2}$ 在 $[0,1]$ 上，$\\lim\\int_0^1 f_n=\\frac{1}{2}$ 而 $\\int_0^1\\lim f_n=0$。原因是？","options":[{"label":"收斂不是一致的：$\\|f_n\\|_\\infty=\\sqrt{\\frac{n}{2}}\\cdot e^{-1/2}\\to\\infty$","correct":true},{"label":"$f_n$ 不連續","why":"每個 $nx e^{-nx^2}$ 都連續。出問題的是收斂方式，不是 $f_n$ 本身。"},{"label":"積分算錯了，兩者其實相等","why":"$\\int_0^1 f_n=\\frac{1-e^{-n}}{2}\\to\\frac{1}{2}$ 是對的；逐點極限 0 的積分是 0。它們真的不相等。"}]},{"ask":"$(\\frac{1}{n})e^{-x/n}$ 在 $[0,\\infty)$ 上一致收斂到 0，積分卻一直是 1。違反了定理的哪個條件？","options":[{"label":"區間要有界","correct":true},{"label":"$f_n$ 要連續","why":"$(\\frac{1}{n})e^{-x/n}$ 是連續的。問題在 $(b-a)\\|f_n-f\\|_\\infty$ 這個上界在 $b=\\infty$ 時變成 $\\infty\\cdot0$。"},{"label":"要一致收斂","why":"這個例子是一致收斂的（$\\|f_n\\|_\\infty=\\frac{1}{n}$）。它說明的是一致收斂還不夠，區間也要有界。"}]},{"ask":"$\\sum_{k=1}^\\infty\\frac{1}{k\\cdot2^k}$ 等於？","options":[{"label":"$\\ln2$","correct":true},{"label":"1","why":"你算的是 $\\sum\\frac{1}{2^k}$，漏了 $\\frac{1}{k}$。$\\frac{1}{k}$ 來自 $\\int x^{k-1}\\,dx$ 生出的分母。"},{"label":"$\\ln(\\frac{3}{2})$","why":"那是 $\\sum\\frac{1}{k\\cdot3^k}$，對應積分到 $\\frac{1}{3}$。這裡積分上限是 $\\frac{1}{2}$：$\\int_0^{1/2}\\frac{1}{1-x}\\,dx=\\ln2$。"}]}],"practice":[{"id":"lec-14-q3c","core":true},{"id":"lec-14-q2b","core":true},{"id":"lb-con-003","core":true},{"id":"lb-con-005","core":true},{"id":"lb-con-001"},{"id":"dm-int-002","challenge":true,"note":"挑戰：在 $[0,1]$ 上把 $\\ln(1-x)$ 展開、乘上 $\\ln x$ 後逐項積分；每一項 $\\frac{x^n(-\\ln x)}{n}$ 非負，交換的理由是〈單調收斂定理（測度版）〉，不是一致收斂。"}]},"limit-derivative-swap":{"id":"limit-derivative-swap","prerequisites":["limit-integral-swap","weierstrass-m-test","ftc-part1"],"next":["partitions"],"related":["power-series-calculus"],"objectives":["舉出反例：$f_n$ 一致收斂，極限的導數卻不等於 $\\lim f_n'$，甚至極限不可微。","說出正確的條件：導數列 $f_n'$ 一致收斂，再加上 $f_n$ 在一個點收斂。","用這個定理合法地逐項微分冪級數，算出 $\\sum\\frac{n}{2^n}$ 這類和。"],"concept":[{"heading":"① 值靠近，斜率不一定靠近","body":["$f_n(x)=\\frac{\\sin(nx)}{\\sqrt{n}}$。$|f_n(x)|\\le\\frac{1}{\\sqrt{n}}$，所以 $f_n$ 在 $\\mathbb{R}$ 上一致收斂到 0，極限的導數是 0。但 $f_n'(x)=\\sqrt{n}\\cos(nx)$，$f_n'(0)=\\sqrt{n}\\to\\infty$。","直覺，不是證明：振幅小、抖得快的函數，值可以很小，斜率卻很大。一致收斂只管「高度差」，不管「斜率差」。","更糟的例子：$\\sqrt{x^2+\\frac{1}{n}}$ 在 $[-1,1]$ 上一致收斂到 $|x|$（範例 3），每個 $f_n$ 都可微，極限在 0 卻不可微。"]},{"heading":"② 正確的定理：條件要放在導數上","body":["設每個 $f_n$ 在 $[a,b]$ 上連續可微，且 (1) $f_n'$ 在 $[a,b]$ 上一致收斂到某個 $g$；(2) 存在一點 $x_0\\in[a,b]$ 使 $f_n(x_0)$ 收斂。則 $f_n$ 在 $[a,b]$ 上一致收斂到某個 $f$，$f$ 可微，而且 $f'=g$，也就是 $(\\lim f_n)'=\\lim f_n'$。","條件 (2) 不能省：$f_n(x)=n$（常數）的導數全是 0，一致收斂到 0，但 $f_n$ 本身發散。導數只決定形狀，要一個點把高度釘住。"]},{"heading":"③ 級數版：逐項微分","body":["若 $\\sum u_n'$ 在 $[a,b]$ 上一致收斂，且 $\\sum u_n(x_0)$ 收斂，則 $(\\sum u_n)'=\\sum u_n'$。冪級數逐項微分後收斂半徑不變，所以在每個 $[-r,r]$（$r<R$）上導數級數由 $M$ 判別一致收斂，逐項微分在 $(-R,R)$ 內處處合法（這就是〈冪級數的微分與積分〉背後的理由）。"]},{"heading":"證明（$f_n'$ 連續的版本）","body":["$g$ 是連續函數 $f_n'$ 的一致極限，所以連續。令 $L=\\lim f_n(x_0)$，定義 $f(x)=L+\\int_{x_0}^{x} g(t)\\,dt$。","由〈微積分基本定理 I〉，$f_n(x)=f_n(x_0)+\\int_{x_0}^{x} f_n'(t)\\,dt$。相減：$|f_n(x)-f(x)|\\le|f_n(x_0)-L|+|\\int_{x_0}^{x}(f_n'-g)\\,dt|\\le|f_n(x_0)-L|+(b-a)\\|f_n'-g\\|_\\infty$。右邊與 $x$ 無關且 $\\to0$，所以 $f_n\\to f$ 一致收斂。","$g$ 連續，再用一次〈微積分基本定理 I〉：$f'(x)=g(x)$。","補充：不假設 $f_n'$ 連續時定理仍成立，證明改用均值定理估計 $(f_n-f_m)(x)-(f_n-f_m)(y)$，比較長，這裡不寫。"],"collapsible":true}],"workedExamples":[{"title":"一致收斂，導數卻爆掉","prompt":"$f_n(x)=\\frac{\\sin(nx)}{\\sqrt{n}}$。求 $\\|f_n\\|_\\infty$ 與 $f_n'(0)$，說明為什麼不能交換。","steps":["$|\\sin(nx)|\\le1$，且 $x=\\frac{\\pi}{2n}$ 時取到 1，所以 $\\|f_n\\|_\\infty=\\frac{1}{\\sqrt{n}}\\to0$：$f_n$ 一致收斂到 $f\\equiv0$，$f'\\equiv0$。","$f_n'(x)=\\frac{n\\cos(nx)}{\\sqrt{n}}=\\sqrt{n}\\cos(nx)$，$f_n'(0)=\\sqrt{n}\\to\\infty$。","$\\lim f_n'(0)$ 不存在，不等於 $f'(0)=0$。定理的條件 (1) 不成立：$f_n'$ 連逐點都不收斂。"],"answer":"$\\|f_n\\|_\\infty=\\frac{1}{\\sqrt{n}}\\to0$，但 $f_n'(0)=\\sqrt{n}\\to\\infty$"},{"title":"逐項微分求和","prompt":"求 $\\sum_{n=1}^\\infty\\frac{n}{2^n}$。","problemId":"lec-14-q3a","steps":["從 $\\sum_{n=0}^\\infty x^n=\\frac{1}{1-x}$（$|x|<1$）出發，想逐項微分。","檢查條件：固定 $r<1$，在 $[-r,r]$ 上 $|n x^{n-1}|\\le n r^{n-1}$，$\\sum n r^{n-1}$ 由比值判別收斂（比值 $\\to r<1$）。由 $M$ 判別，導數級數一致收斂；原級數在 $x_0=0$ 收斂。","所以在 $(-1,1)$ 內 $\\sum_{n=1}^\\infty n x^{n-1}=(\\frac{1}{1-x})'=\\frac{1}{(1-x)^2}$。兩邊乘 $x$：$\\sum n x^n=\\frac{x}{(1-x)^2}$。","$x=\\frac{1}{2}$：$\\frac{\\frac{1}{2}}{(\\frac{1}{2})^2}=2$。"],"answer":"2"},{"title":"可微函數的一致極限不可微","prompt":"$f_n(x)=\\sqrt{x^2+\\frac{1}{n}}$，$x\\in[-1,1]$。證明 $f_n\\to|x|$ 一致收斂，並說明定理哪個條件不成立。","steps":["分子有理化：$0\\le\\sqrt{x^2+\\frac{1}{n}}-|x|=\\frac{\\frac{1}{n}}{\\sqrt{x^2+\\frac{1}{n}}+|x|}\\le\\frac{\\frac{1}{n}}{\\sqrt{\\frac{1}{n}}}=\\frac{1}{\\sqrt{n}}$。上界與 $x$ 無關，所以一致收斂到 $|x|$。","每個 $f_n$ 可微：$f_n'(x)=\\frac{x}{\\sqrt{x^2+\\frac{1}{n}}}$。","$f_n'(x)$ 逐點趨近 $\\operatorname{sign}(x)$（$x>0$ 為 1、$x<0$ 為 $-1$、$x=0$ 為 0），極限不連續，而每個 $f_n'$ 連續，所以 $f_n'$ 不一致收斂：條件 (1) 不成立。極限 $|x|$ 在 0 不可微，與定理不衝突。"],"answer":"$\\|f_n-|x|\\|_\\infty\\le\\frac{1}{\\sqrt{n}}$；$f_n'$ 不一致收斂"}],"pitfalls":["以為 $f_n$ 一致收斂就能寫 $(\\lim f_n)'=\\lim f_n'$。要檢查的是 $f_n'$。","忘了「某一點 $f_n(x_0)$ 收斂」這個條件。","逐項微分冪級數之後，忘了 $\\sum n x^{n-1}$ 要乘 $x$ 才是 $\\sum n x^n$。","在收斂區間的端點逐項微分。端點上導數級數可能發散，例如 $\\sum\\frac{x^n}{n^2}$ 在 $x=1$ 收斂，導數級數 $\\sum\\frac{x^{n-1}}{n}$ 在 $x=1$ 發散。"],"voice":"d98147c4","sections":[{"title":"值靠近，斜率不一定","beats":[{"show":["$f_n(x)=\\frac{\\sin(nx)}{\\sqrt{n}}$"],"say":"看 sine n x 除以根號 n。振幅越來越小，可是抖得越來越快。","t":[0,6840]},{"show":["$\\|f_n\\|_\\infty=\\frac{1}{\\sqrt{n}}\\to0$"],"note":"一致收斂到 0，極限的導數是 0。","say":"高度不超過根號 n 分之一，所以一致收斂到零，極限函數的導數當然是零。","t":[6840,14184]},{"show":["$f_n'(x)=\\sqrt{n}\\cos(nx)$，$f_n'(0)=\\sqrt{n}\\to\\infty$"],"say":"可是微分一下，導數是根號 n 乘 cosine n x，在零是根號 n，衝到無限大。","t":[14184,21768]},{"show":["一致收斂只管高度差，不管斜率差"],"say":"值可以很小，斜率卻很大。一致收斂只管高度，不管斜率。","t":[21768,28728]}],"check":0},{"title":"可微的極限不可微","beats":[{"show":["$f_n(x)=\\sqrt{x^2+\\frac{1}{n}}$，$[-1,1]$"],"say":"更糟的例子：根號 x 平方加 n 分之一，在負一到一。每一個都很光滑，處處可微。","t":[28728,37680]},{"show":["$0\\le f_n(x)-|x|\\le\\frac{1}{\\sqrt{n}}$"],"note":"分子有理化。","say":"分子有理化，跟 x 的絕對值差不超過根號 n 分之一，跟 x 無關，一致收斂到絕對值 x。","t":[37680,45936]},{"show":["極限 $|x|$ 在 0 不可微"],"say":"可是絕對值 x 在零有尖角，不可微。光滑函數的一致極限，可以有尖角。","t":[45936,54048]},{"show":["$f_n'(x)=\\frac{x}{\\sqrt{x^2+\\frac{1}{n}}}\\to\\operatorname{sign}(x)$"],"note":"極限在 0 不連續。","say":"看導數：它逐點趨近 sign x，正的是一、負的是負一、零是零，在零斷掉了。","t":[54048,62232]}],"predict":{"ask":"所以 $f_n'$ 的收斂是？","options":[{"label":"不一致：連續函數的極限不連續","correct":true},{"label":"一致，因為 $f_n$ 一致收斂","why":"$f_n$ 一致不代表 $f_n'$ 一致；每個 $f_n'$ 連續而極限 $\\operatorname{sign}(x)$ 不連續，就不可能一致。"},{"label":"連逐點都不收斂","why":"每個 $x$ 上 $f_n'(x)$ 都有極限：$x>0$ 為 1、$x<0$ 為 $-1$、$x=0$ 為 0。"}]}},{"title":"條件放在導數上","beats":[{"show":["(1) $f_n'$ 在 $[a,b]$ 一致收斂到 $g$"],"note":"每個 $f_n$ 連續可微。","say":"正確的定理把條件放在導數上：第一，導數 f n prime 一致收斂到某個 g。","t":[62232,69216]},{"show":["(2) 某一點 $f_n(x_0)$ 收斂"],"say":"第二，至少有一個點，f n 在那裡的值收斂。","t":[69216,73920]},{"show":["$\\Rightarrow(\\lim f_n)'=\\lim f_n'$"],"note":"而且 $f_n$ 一致收斂到 $f$，$f'=g$。","say":"這樣 f n 就一致收斂到某個 f，f 可微，導數就是 g。極限和微分可以交換。證明在後面那節。","t":[73920,84600]}],"check":1},{"title":"一個點釘住高度","beats":[{"show":["$f_n(x)=n$（常數）"],"say":"為什麼要第二個條件？看常數函數 f n 等於 n。","t":[84600,90192]},{"show":["$f_n'=0$，一致收斂到 0"],"note":"但 $f_n$ 本身發散。","say":"它們的導數全是零，當然一致收斂；可是 f n 本身一路往上跑，沒有極限。","t":[90192,97632]},{"show":["導數決定形狀，一個點釘住高度"],"say":"導數只決定形狀，要一個點把高度釘住，整條才收斂。","t":[97632,103392]}],"check":2},{"title":"證明：先把 $f$ 造出來","proof":true,"of":3,"skeleton":"構造","beats":[{"show":["釘住高度，把 $g$ 積分回去"],"note":"$f_n'$ 連續的版本。","say":"策略：直接把答案造出來。用那一點釘住高度，把 g 積分回去，再證 f n 一致收斂到它。","t":[103392,112896]},{"show":["$f(x)=L+\\int_{x_0}^{x}g(t)\\,dt$"],"note":"$L=\\lim f_n(x_0)$；$g$ 連續，積分有意義。","why":{"ask":"為什麼 $g$ 連續？","say":"要積分 g，g 最好連續。它為什麼連續？","options":[{"label":"$g$ 是連續函數 $f_n'$ 的一致極限","correct":true},{"label":"每個 $f_n'$ 都連續，極限當然連續","why":"逐點極限保不住連續：$\\frac{x}{\\sqrt{x^2+\\frac{1}{n}}}$ 都連續，極限在 0 斷掉。要一致收斂才保得住。"},{"label":"$f_n$ 一致收斂","why":"這還沒證，是等一下才要證的；而且它管的是 $f_n$，不是導數。"}],"t":[112896,118128]},"say":"g 是連續函數 f n prime 的一致極限，所以連續。L 是那一點的極限，用來釘住高度。","t":[118128,126936]},{"show":["$f_n(x)=f_n(x_0)+\\int_{x_0}^{x}f_n'(t)\\,dt$"],"note":"微積分基本定理 I。","say":"每一個 f n 也能寫成同樣的樣子：那一點的值，加上導數的積分。","t":[126936,133248]},{"show":["$|f_n(x)-f(x)|\\le|f_n(x_0)-L|$","$+(b-a)\\|f_n'-g\\|_\\infty$"],"note":"右邊與 $x$ 無關，而且 $\\to0$。","why":{"ask":"這為什麼推得出一致收斂？","say":"兩式相減，差被右邊蓋住。為什麼這就是一致收斂？","options":[{"label":"右邊與 $x$ 無關，而且趨近 0","correct":true},{"label":"對每個 $x$，左邊都趨近 0","why":"每個 $x$ 各自趨近 0 只是逐點收斂；一致要的是一個不看 $x$ 的上界趨近 0。"},{"label":"$f_n'$ 一致收斂，$f_n$ 就一致收斂","why":"光有導數不夠：$f_n=n$ 的導數一致收斂，$f_n$ 卻發散。還要第一項 $|f_n(x_0)-L|\\to0$。"}],"t":[133248,139392]},"say":"相減，積分不超過區間長度乘最大誤差。右邊兩項都跟 x 無關又趨近零，所以一致收斂。","t":[139392,149040]},{"show":["$f'(x)=g(x)$"],"note":"$g$ 連續，再用一次基本定理。","say":"最後，g 連續，對 f 再用一次微積分基本定理，f prime 就是 g。極限和微分交換了。","t":[149040,158112]}],"where":{"ask":"條件 (2)「$f_n(x_0)$ 收斂」用在哪一步？","steps":[{"label":"$g$ 連續","why":"這只用到 $f_n'$ 連續、而且一致收斂到 $g$。"},{"label":"取 $L=\\lim f_n(x_0)$，定義 $f$","correct":true},{"label":"$f_n(x)=f_n(x_0)+\\int_{x_0}^{x}f_n'$","why":"這是基本定理用在每一個 $f_n$ 上，跟 $n$ 趨近無限大無關。"}]}},{"title":"逐項微分求和","beats":[{"show":["$\\sum_{n=0}^\\infty x^n=\\frac{1}{1-x}$，$|x|<1$"],"note":"目標：$\\sum_{n=1}^\\infty\\frac{n}{2^n}$。","say":"想求 n 除以二的 n 次方的和。從幾何級數出發，打算逐項微分。","t":[158112,165360]},{"show":["$[-r,r]$ 上 $|n x^{n-1}|\\le n r^{n-1}$"],"note":"$\\sum n r^{n-1}$ 收斂；$x_0=0$ 處原級數收斂。","say":"先檢查條件：在負 r 到 r 上，導數級數被一個收斂的數字級數蓋住，M 判別說一致收斂。","t":[165360,173928]},{"show":["$\\sum_{n=1}^\\infty n x^{n-1}=\\frac{1}{(1-x)^2}$"],"say":"所以可以逐項微分：n 乘 x 的 n 減一次方加起來，等於一減 x 平方分之一。","t":[173928,181056]},{"show":["乘 $x$：$\\sum n x^n=\\frac{x}{(1-x)^2}$"],"note":"再代 $x=\\frac{1}{2}$。","say":"兩邊乘 x，得到 n 乘 x 的 n 次方的和。最後代 x 等於二分之一。","t":[181056,188232]}],"check":3}],"checks":[{"ask":"$f_n(x)=\\frac{\\sin(nx)}{\\sqrt{n}}$ 在 $\\mathbb{R}$ 上一致收斂到 0。下列何者正確？","options":[{"label":"$f_n'(0)=\\sqrt{n}\\to\\infty$，所以 $\\lim f_n'\\ne(\\lim f_n)'$","correct":true},{"label":"一致收斂，所以 $f_n'\\to0$","why":"你把一致收斂當成也管導數。$f_n'(x)=\\sqrt{n}\\cos(nx)$，在 $x=0$ 是 $\\sqrt{n}$。"},{"label":"$f_n$ 其實不一致收斂，因為導數發散","why":"一致收斂只看 $\\|f_n-0\\|_\\infty=\\frac{1}{\\sqrt{n}}\\to0$，跟導數無關。"}]},{"ask":"要保證 $(\\lim f_n)'=\\lim f_n'$，定理主要的條件是？","options":[{"label":"$f_n'$ 一致收斂，且某一點 $f_n(x_0)$ 收斂","correct":true},{"label":"$f_n$ 一致收斂，且每個 $f_n$ 可微","why":"$\\sqrt{x^2+\\frac{1}{n}}\\to|x|$ 就滿足這兩個條件，極限卻在 0 不可微。條件要放在導數上。"},{"label":"$f_n'$ 逐點收斂","why":"$\\sqrt{x^2+\\frac{1}{n}}$ 的導數逐點收斂到 $\\operatorname{sign}(x)$，但極限函數 $|x|$ 在 0 沒有導數。逐點不夠。"}]},{"ask":"$f_n(x)=n$（常數函數）。$f_n'=0$ 一致收斂到 0。為什麼不能說 $\\lim f_n$ 的導數是 0？","options":[{"label":"$f_n$ 本身沒有極限：缺了「某一點 $f_n(x_0)$ 收斂」","correct":true},{"label":"其實可以，$\\lim f_n$ 的導數就是 0","why":"$\\lim f_n$ 根本不存在（$n\\to\\infty$），沒有函數可以求導。"},{"label":"因為 $f_n'$ 不是一致收斂","why":"$f_n'$ 全是 0，當然一致收斂。缺的是把高度釘住的那個點。"}]},{"ask":"$\\sum_{n=1}^\\infty\\frac{n}{2^n}$ 等於？","options":[{"label":"2","correct":true},{"label":"4","why":"你算的是 $\\sum n x^{n-1}=\\frac{1}{(1-x)^2}$ 在 $x=\\frac{1}{2}$ 的值，還要乘上 $x=\\frac{1}{2}$。"},{"label":"1","why":"那是 $\\sum\\frac{1}{2^n}$。分子的 $n$ 要靠逐項微分生出來。"}]}],"practice":[{"id":"lec-14-q3a","core":true},{"id":"fd-serx-204","core":true},{"id":"tmpl-ser-arith-geo-001","core":true},{"id":"lec-14-q3b","challenge":true,"note":"挑戰：$\\sum\\frac{n^2}{2^n}$ 要逐項微分兩次（或對 $\\sum n x^n$ 再微分一次再乘 $x$）。"}]}});
